    low: "bg-blue-50 text-blue-800 border-blue-100"
  };

  return (
    <span className={`inline-block px-3 py-1 border rounded-full text-xs font-semibold uppercase tracking-wide ${colors[level]}`}>
      {label}
    </span>
  );
};

export default Badge;

import React, { useState, useEffect, useCallback } from 'react';
import { Language, AnalysisResult, SavedAnalysis, RiskLevel } from './types';
import { TRANSLATIONS } from './constants';
import { parsePDF } from './services/pdfService';
import { analyzeContract } from './services/geminiService';
import { encryptData, decryptData } from './services/cryptoService';
import Button from './components/Button';
import Badge from './components/Badge';
import Onboarding from './components/Onboarding';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [savedAnalyses, setSavedAnalyses] = useState<SavedAnalysis[]>([]);
  const [isSaving, setIsSaving] = useState(false);

  const t = TRANSLATIONS[lang];

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);

    const saved = JSON.parse(localStorage.getItem('contractcheck_saved') || '[]');
    setSavedAnalyses(saved);

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError('Please upload a PDF document.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('File too large. Max 10MB.');
      return;
    }

    setLoading(true);
    setError(null);
    setAnalysis(null);

    try {
      setLoadingText('Extracting contract text...');
      const text = await parsePDF(file);

      setLoadingText('AI is analyzing risk factors...');
      const result = await analyzeContract(text);
      setAnalysis(result);
    } catch (err: any) {
      setError(err.message || 'Analysis failed. Please try again.');
    } finally {
      setLoading(false);
      setLoadingText('');
      e.target.value = '';
    }
  };

  const saveAnalysis = async () => {
    if (!analysis) return;
    const password = prompt('Set a password to encrypt this analysis:');
    if (!password) return;

    setIsSaving(true);
    try {
      const encrypted = await encryptData(analysis, password);
      const newSaved: SavedAnalysis = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        encrypted
      };
      const updatedList = [...savedAnalyses, newSaved];
      setSavedAnalyses(updatedList);
      localStorage.setItem('contractcheck_saved', JSON.stringify(updatedList));
      alert('Analysis saved securely with AES-GCM encryption.');
    } catch (err) {
      alert('Encryption failed.');
    } finally {
      setIsSaving(false);
    }
  };

  const loadSavedAnalysis = async (item: SavedAnalysis) => {
    const password = prompt('Enter your encryption password:');
    if (!password) return;

    try {
      const decrypted = await decryptData(item.encrypted, password);
      setAnalysis(decrypted);
      setError(null);
    } catch (err) {
      alert('Incorrect password or corrupted data.');
    }
  };

  const deleteSaved = (id: number) => {
    if (!confirm('Are you sure you want to delete this record?')) return;
    const updated = savedAnalyses.filter(a => a.id !== id);
    setSavedAnalyses(updated);
    localStorage.setItem('contractcheck_saved', JSON.stringify(updated));
  };

  const closeOnboarding = (dontShow: boolean) => {
    if (dontShow) localStorage.setItem('contractcheck_onboarding_seen', 'true');
    setShowOnboarding(false);
  };

  return (
    <div className="min-h-screen flex flex-col">
      {showOnboarding && <Onboarding onClose={closeOnboarding} />}

      {/* Header */}
      <header className="bg-blue-900 text-white shadow-lg sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h1 className="text-3xl font-bold tracking-tight">ContractCheck</h1>
              <p className="text-blue-200 text-sm mt-1">AI-Powered SA Contract Risk Triage</p>
            </div>
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <select 
                value={lang} 
                onChange={(e) => setLang(e.target.value as Language)}
                className="bg-blue-800 text-white px-3 py-2 rounded-lg border border-blue-700 outline-none focus:ring-2 focus:ring-blue-400 min-h-[48px]"
              >
                <option value="en">English</option>
                <option value="af">Afrikaans</option>
                <option value="zu">isiZulu</option>
              </select>
              <button 
                onClick={() => setShowOnboarding(true)}
                className="p-3 bg-blue-800 rounded-lg hover:bg-blue-700 transition min-h-[48px] min-w-[48px]"
                aria-label="Help"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              </button>
              <div className={`flex items-center gap-2 px-4 py-2 rounded-lg ${isOnline ? 'bg-green-800' : 'bg-red-800'}`}>
                <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-green-400' : 'bg-red-400'}`}></span>
                <span className="text-xs font-semibold">{isOnline ? 'ONLINE' : 'OFFLINE'}</span>
              </div>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8">
        {/* Offline Notice */}
        {!isOnline && (
          <div className="bg-blue-50 border-l-4 border-blue-600 p-6 rounded-xl mb-6 flex gap-4 items-start fade-in">
            <svg className="w-6 h-6 text-blue-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <div>
              <h3 className="font-bold text-blue-900">Offline Mode</h3>
              <p className="text-blue-800 text-sm mt-1">You can view saved analyses. Reconnect to process new contracts.</p>
            </div>
          </div>
        )}

        {/* Disclaimer */}
        <div className="bg-gray-100 border border-gray-200 rounded-xl p-5 mb-8 flex gap-4 items-start">
          <span className="text-2xl opacity-50">⚠️</span>
          <div>
            <h3 className="font-bold text-gray-900 text-sm uppercase tracking-wider mb-1">Legal Disclaimer</h3>
            <p className="text-sm text-gray-600 leading-relaxed">
              ContractCheck provides risk awareness only. This is <strong>not legal advice</strong>. Professional consultation is essential for high-risk legal matters.
            </p>
          </div>
        </div>

        {/* Upload Section */}
        {!analysis && !loading && (
          <div className="card-base mb-8 fade-in">
            <h2 className="text-2xl font-bold mb-3">Analyze Contract</h2>
            <p className="text-gray-600 mb-8">Upload a PDF to scan for legal risks under South African law.</p>

            <div className="group relative border-2 border-dashed border-gray-200 rounded-2xl p-12 text-center transition-all hover:border-blue-400 hover:bg-blue-50/50 cursor-pointer">
              <input 
                type="file" 
                accept=".pdf" 
                onChange={handleFileUpload} 
                className="absolute inset-0 opacity-0 cursor-pointer z-10"
              />
              <div className="space-y-4">
                <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto text-blue-600 group-hover:scale-110 transition-transform">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/></svg>
                </div>
                <div>
                  <p className="text-lg font-semibold text-gray-900">Click to upload or drag & drop</p>
                  <p className="text-sm text-gray-500 mt-1">PDF documents only (max 10MB)</p>
                </div>
              </div>
            </div>

            {error && (
              <div className="mt-6 p-4 bg-red-50 border-l-4 border-red-600 rounded-lg text-red-800 text-sm flex gap-3 fade-in">
                <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                {error}
              </div>
            )}
          </div>
        )}

        {/* Loading State */}
        {loading && (
          <div className="card-base text-center py-20 fade-in">
            <div className="inline-block relative w-20 h-20 mb-6">
              <div className="absolute inset-0 border-4 border-blue-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <h3 className="text-xl font-bold mb-2">{loadingText}</h3>
            <p className="text-gray-500">This usually takes 15-30 seconds depending on complexity.</p>
          </div>
        )}

        {/* Results View */}
        {analysis && (
          <div className="fade-in space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
              <h2 className="text-2xl font-bold">Analysis Results</h2>
              <div className="flex gap-3 w-full sm:w-auto">
                <Button variant="secondary" onClick={() => { setAnalysis(null); setError(null); }}>New Scan</Button>
                <Button onClick={saveAnalysis} disabled={isSaving}>Save Analysis</Button>
              </div>
            </div>

            {/* Risk Summary Card */}
            <div className={`p-8 rounded-2xl border-t-4 shadow-sm bg-white ${analysis.overallRisk === 'high' ? 'border-red-600' : analysis.overallRisk === 'medium' ? 'border-amber-500' : 'border-blue-600'}`}>
              <div className="flex items-center gap-4 mb-4">
                <div className={`w-4 h-4 rounded-full ${analysis.overallRisk === 'high' ? 'bg-red-600' : analysis.overallRisk === 'medium' ? 'bg-amber-500' : 'bg-blue-600'}`}></div>
                <h3 className="text-xl font-bold text-gray-900">{t.overallRisk}: {t[`${analysis.overallRisk}Risk` as keyof typeof t]}</h3>
              </div>
              <p className="text-gray-600">
                We've flagged <strong>{analysis.flaggedClauses.length} clauses</strong> for your attention. 
                {analysis.flaggedClauses.length === 0 && t.noIssues}
              </p>
              {analysis.uncertainty && (
                <div className="mt-4 p-4 bg-gray-50 rounded-xl text-sm text-gray-500 border border-gray-200 italic">
                  <strong>Note:</strong> {analysis.uncertainty}
                </div>
              )}
            </div>

            {/* Flagged Clauses List */}
            <div className="space-y-4">
              {analysis.flaggedClauses.map((clause, idx) => (
                <div key={idx} className={`card-base border-l-4 ${clause.riskLevel === 'high' ? 'border-red-600' : clause.riskLevel === 'medium' ? 'border-amber-500' : 'border-blue-600'}`}>
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-bold text-gray-900">{clause.issue}</h4>
                    <Badge level={clause.riskLevel} label={t[`${clause.riskLevel}Risk` as keyof typeof t]} />
                  </div>

                  <div className="mb-6">
                    <p className="text-xs font-semibold text-gray-500 uppercase tracking-widest mb-2">Verbatim Quote</p>
                    <blockquote className="border-l-4 border-gray-200 pl-4 py-1 italic text-gray-700 bg-gray-50 rounded-r-lg leading-relaxed">
                      "{clause.clauseText}"
                    </blockquote>
                  </div>

                  <div className="grid md:grid-cols-2 gap-8">
                    <div>
                      <h5 className="text-sm font-bold text-gray-900 mb-2">{t.analysis}</h5>
                      <p className="text-gray-600 text-sm leading-relaxed">{clause.analysis}</p>
                    </div>
                    <div>
                      <h5 className="text-sm font-bold text-gray-900 mb-2">{t.recommendation}</h5>
                      <p className="text-gray-600 text-sm leading-relaxed">{clause.recommendation}</p>
                    </div>
                  </div>

                  {clause.uncertainty && (
                    <div className="mt-6 pt-4 border-t text-xs text-gray-400">
                      <strong>Uncertainty:</strong> {clause.uncertainty}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Saved Section */}
        {savedAnalyses.length > 0 && (
          <div className="mt-16">
            <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
              <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
              Saved Securely
            </h3>
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {savedAnalyses.map((item) => (
                <div key={item.id} className="bg-white border border-gray-200 rounded-2xl p-6 hover:shadow-md transition-shadow">
                  <p className="text-xs font-semibold text-gray-400 mb-1">RECORDED ON</p>
                  <p className="font-bold text-gray-800 mb-6">{new Date(item.timestamp).toLocaleString()}</p>
                  <div className="flex gap-2">
                    <Button size="sm" onClick={() => loadSavedAnalysis(item)} className="flex-1">Unlock</Button>
                    <Button size="sm" variant="secondary" onClick={() => deleteSaved(item.id)} className="bg-transparent border-red-200 text-red-600 hover:bg-red-50">Delete</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      <footer className="bg-gray-900 text-gray-400 py-12 mt-16">
        <div className="max-w-7xl mx-auto px-4 text-center space-y-4">
          <p className="text-sm">
            <span className="font-bold text-white mr-2">Privacy Notice:</span> 
            All contract processing is local. Optional encrypted saves use standard AES-GCM encryption.
          </p>
          <div className="flex justify-center gap-4 text-xs font-semibold uppercase tracking-widest opacity-60">
            <span>POPIA COMPLIANT</span>
            <span>NO DATA STORAGE</span>
            <span>SECURE AES-GCM</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  icon?: React.ReactNode;
  loading?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon, 
  loading,
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-semibold transition-all duration-200 active:scale-95 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:active:scale-100";

  const variants = {
    primary: "bg-blue-600 text-white shadow-sm hover:bg-blue-700 hover:shadow-md focus:ring-blue-500",
    secondary: "bg-white border border-slate-200 text-slate-700 shadow-sm hover:bg-slate-50 hover:border-slate-300 focus:ring-slate-300",
    danger: "bg-white border border-red-200 text-red-600 hover:bg-red-50 hover:border-red-300 focus:ring-red-500",
    ghost: "bg-transparent text-slate-500 hover:bg-slate-100 hover:text-slate-700 focus:ring-slate-200"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm rounded-lg",
    md: "px-5 py-2.5 text-base rounded-xl",
    lg: "px-8 py-4 text-lg rounded-2xl"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={loading || props.disabled}
      {...props}
    >
      {loading ? (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : icon && (
        <span className="mr-2">{icon}</span>
      )}
      {children}
    </button>
  );
};

export default Button;

