          <div className="flex justify-center gap-8 opacity-40">
            <span className="text-[10px] font-black tracking-widest uppercase">Privacy First</span>
            <span className="text-[10px] font-black tracking-widest uppercase">POPIA Ready</span>
            <span className="text-[10px] font-black tracking-widest uppercase">AES-256 GCM</span>
          </div>
          <p className="text-xs text-slate-400 leading-relaxed max-w-sm mx-auto">
            ContractCheck is an educational risk assessment tool. Information provided is not legal advice and should not be relied upon for critical decision making.
          </p>
          <p className="text-[10px] font-bold text-slate-300">© {new Date().getFullYear()} ContractCheck SA</p>
        </div>
      </footer>
    </div>
  );
};

