import Badge from './components/Badge';
import Onboarding from './components/Onboarding';
import RiskGauge from './components/RiskGauge';

const SAMPLE_CONTRACT = `
LEASE AGREEMENT
1. PARTIES: Landlord (Smith) and Tenant (Jones).
2. DEPOSIT: Tenant shall pay a deposit of R10,000. Landlord may retain the entire deposit for any reason at their sole discretion at the end of the lease, regardless of the condition of the property.
3. ACCESS: Landlord may enter the premises at any time of day or night without prior notice to the Tenant for any reason.
4. LIABILITY: The Tenant waives all rights to claim damages from the Landlord for any injury occurring on the property, even if caused by the Landlord's gross negligence or intentional failure to maintain the structure.
5. TERMINATION: The Landlord may terminate this lease with 24 hours' notice if they decide to sell the property. The Tenant must vacate immediately.
6. POPIA: Tenant hereby grants Landlord permission to sell Tenant's personal data, including credit records and identity numbers, to any third-party marketing company without further consent.
`;

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [savedAnalyses, setSavedAnalyses] = useState<SavedAnalysis[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const t = TRANSLATIONS[lang];
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);

    const saved = JSON.parse(localStorage.getItem('contractcheck_saved') || '[]');
    setSavedAnalyses(saved);

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processText = async (text: string) => {
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setProgress(30);
    setLoadingText('Analyzing risk factors with AI...');

    try {
      // Simulate some progress increments
      const progressInterval = setInterval(() => {
        setProgress(prev => (prev < 90 ? prev + 5 : prev));
      }, 1000);

      const result = await analyzeContract(text);
      clearInterval(progressInterval);
      setProgress(100);
      setAnalysis(result);
    } catch (err: any) {
      setError(err.message || 'Analysis failed. This could be due to complex content or connectivity.');
    } finally {
      setTimeout(() => {
        setLoading(false);
        setLoadingText('');
        setProgress(0);
      }, 500);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | undefined;

    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e) {
      e.preventDefault();
      setIsDragging(false);
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError('Please upload a valid PDF document.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('File too large. Max allowed size is 10MB.');
      return;
    }

    setLoading(true);
    setError(null);
    setAnalysis(null);
    setProgress(5);
    setLoadingText('Parsing PDF document structure...');

    try {
      const text = await parsePDF(file);
      setProgress(20);
      await processText(text);
    } catch (err: any) {
      setError(err.message || 'Failed to read PDF. The file might be corrupted or protected.');
      setLoading(false);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const loadSample = () => {
    processText(SAMPLE_CONTRACT);
  };

  const saveAnalysis = async () => {
    if (!analysis) return;
    const password = prompt('Secure your data. Set a password to encrypt this analysis:');
    if (!password) return;

    setIsSaving(true);
    try {
      const encrypted = await encryptData(analysis, password);
      const newSaved: SavedAnalysis = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        encrypted
      };
      const updatedList = [newSaved, ...savedAnalyses];
      setSavedAnalyses(updatedList);
      localStorage.setItem('contractcheck_saved', JSON.stringify(updatedList));
    } catch (err) {
      alert('Encryption process failed.');
    } finally {
      setIsSaving(false);
    }
  };

  const loadSavedAnalysis = async (item: SavedAnalysis) => {
    const password = prompt('Enter the decryption password for this record:');
    if (!password) return;

    try {
      const decrypted = await decryptData(item.encrypted, password);
      setAnalysis(decrypted);
      setError(null);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      alert('Incorrect password or record integrity check failed.');
    }
  };

  const deleteSaved = (id: number) => {
    if (!confirm('Permanently delete this record?')) return;
    const updated = savedAnalyses.filter(a => a.id !== id);
    setSavedAnalyses(updated);
    localStorage.setItem('contractcheck_saved', JSON.stringify(updated));
  };

  const closeOnboarding = (dontShow: boolean) => {
    if (dontShow) localStorage.setItem('contractcheck_onboarding_seen', 'true');
    setShowOnboarding(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col antialiased">
      {showOnboarding && <Onboarding onClose={closeOnboarding} />}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-blue-200 shadow-lg">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-900 leading-tight">ContractCheck</h1>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">SA Risk Intelligence</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <select 
                value={lang} 
                onChange={(e) => setLang(e.target.value as Language)}
                className="hidden sm:block bg-slate-100 text-slate-700 text-sm font-semibold px-3 py-2 rounded-lg border-none outline-none focus:ring-2 focus:ring-blue-100 cursor-pointer"
              >
                <option value="en">English</option>
                <option value="af">Afrikaans</option>
                <option value="zu">isiZulu</option>
              </select>
              <button 
                onClick={() => setShowOnboarding(true)}
                className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
                title="Help & Info"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              </button>
              <div className={`hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${isOnline ? 'border-emerald-100 bg-emerald-50 text-emerald-700' : 'border-red-100 bg-red-50 text-red-700'}`}>
                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isOnline ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
                <span className="text-[10px] font-bold tracking-tight">{isOnline ? 'LIVE' : 'OFFLINE'}</span>
              </div>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full px-4 sm:px-6 py-10">

        {!isOnline && (
          <div className="mb-8 p-4 bg-amber-50 border border-amber-200 rounded-2xl flex gap-3 items-start fade-in shadow-sm">
            <svg className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            <p className="text-sm text-amber-800 font-medium">Limited functionality. Connect to the internet for AI analysis.</p>
          </div>
        )}

        {!analysis && !loading && (
          <div className="space-y-8">
            <div className="text-center space-y-3">
              <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">Contract Triage</h2>
              <p className="text-slate-500 max-w-lg mx-auto leading-relaxed">
                Upload a South African legal document or try our sample to see the risk analysis in action.
              </p>
            </div>

            <div 
              className={`relative group transition-all duration-300 ${isDragging ? 'scale-[1.02]' : ''}`}
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={handleFileUpload}
            >
              <div className={`absolute -inset-1 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-3xl blur opacity-10 transition duration-500 ${isDragging ? 'opacity-30' : 'group-hover:opacity-20'}`}></div>
              <div className={`relative border-2 border-dashed rounded-3xl p-16 bg-white transition-all text-center ${isDragging ? 'border-blue-500 bg-blue-50 shadow-2xl' : 'border-slate-200 hover:border-blue-400 hover:shadow-xl'}`}>
                <input 
                  type="file" 
                  accept=".pdf" 
                  ref={fileInputRef}
                  onChange={handleFileUpload} 
                  className="absolute inset-0 opacity-0 cursor-pointer z-10"
                />
                <div className="space-y-6">
                  <div className={`w-20 h-20 rounded-2xl flex items-center justify-center mx-auto transition-all ${isDragging ? 'bg-blue-600 text-white scale-110' : 'bg-blue-50 text-blue-600 group-hover:scale-110'}`}>
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-900">{isDragging ? 'Drop to start analysis' : 'Drop your contract PDF here'}</h3>
                    <p className="text-slate-400 text-sm mt-2">Maximum file size: 10MB</p>
                  </div>
                  <div className="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">
                    <Button size="md" className="pointer-events-none w-full sm:w-auto">Select File</Button>
                    <span className="text-slate-300 text-xs font-bold uppercase">or</span>
                    <Button variant="ghost" size="md" onClick={loadSample} className="w-full sm:w-auto relative z-20">Try Sample Contract</Button>
                  </div>
                </div>
              </div>
            </div>

            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-600 text-sm font-semibold flex items-center gap-3 fade-in">
                <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                {error}
              </div>
            )}
          </div>
        )}

        {loading && (
          <div className="py-24 text-center space-y-10 fade-in">
            <div className="max-w-md mx-auto space-y-4">
              <div className="relative inline-flex mb-4">
                <div className="w-24 h-24 rounded-3xl border-4 border-blue-50 animate-pulse"></div>
                <div className="absolute inset-0 w-24 h-24 rounded-3xl border-4 border-blue-600 border-t-transparent animate-spin"></div>
              </div>
              <div className="space-y-1">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">{loadingText}</h3>
                <p className="text-slate-400 font-medium">Hold tight, our AI is reviewing legal clauses...</p>
              </div>

              {/* Progress Bar */}
              <div className="relative pt-6">
                <div className="flex mb-2 items-center justify-between">
                  <div>
                    <span className="text-xs font-black inline-block py-1 px-2 uppercase rounded-full text-blue-600 bg-blue-100">
                      Processing
                    </span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-bold inline-block text-blue-600">
                      {progress}%
                    </span>
                  </div>
                </div>
                <div className="overflow-hidden h-3 mb-4 text-xs flex rounded-full bg-slate-100">
                  <div 
                    style={{ width: `${progress}%` }} 
                    className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-blue-600 transition-all duration-500 ease-out"
                  ></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {analysis && (
          <div className="fade-in space-y-10 pb-20">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
               <Button variant="ghost" size="sm" onClick={() => { setAnalysis(null); setError(null); }} icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"/></svg>}>
                New Analysis
              </Button>
              <div className="flex gap-2 w-full sm:w-auto">
                <Button size="sm" variant="secondary" onClick={saveAnalysis} loading={isSaving} icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4"/></svg>}>
                  Export & Save
                </Button>
              </div>
            </div>

            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden flex flex-col md:flex-row">
              <div className="p-10 flex flex-col items-center justify-center bg-slate-50 border-b md:border-b-0 md:border-r border-slate-100 min-w-[200px]">
                <RiskGauge level={analysis.overallRisk} label={t[`${analysis.overallRisk}Risk` as keyof typeof t]} />
              </div>
              <div className="p-10 flex-1">
                <h3 className="text-2xl font-black text-slate-900 mb-4">Risk Summary</h3>
                <p className="text-slate-600 leading-relaxed mb-6">
                  {analysis.flaggedClauses.length > 0 
                    ? `AI analysis has identified ${analysis.flaggedClauses.length} clauses that may pose legal risks or are non-compliant with South African laws.`
                    : t.noIssues}
                </p>
                {analysis.uncertainty && (
                  <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 text-sm text-blue-700 font-medium italic">
                    <span className="font-bold uppercase tracking-wider text-[10px] block mb-1">Expert Note</span>
                    {analysis.uncertainty}
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex items-center gap-3 px-2">
                <h4 className="font-black text-slate-900 uppercase tracking-widest text-xs">Identified Liabilities</h4>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              {analysis.flaggedClauses.map((clause, idx) => (
                <div key={idx} className="bg-white rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow overflow-hidden group">
                  <div className={`h-2 ${clause.riskLevel === 'high' ? 'bg-red-500' : clause.riskLevel === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                  <div className="p-8 space-y-6">
                    <div className="flex justify-between items-start gap-4">
                      <div>
                        <h5 className="text-xl font-bold text-slate-900 mb-1">{clause.issue}</h5>
                        <Badge level={clause.riskLevel} label={t[`${clause.riskLevel}Risk` as keyof typeof t]} />
                      </div>
                    </div>

                    <div className="space-y-3">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Verbatim Contract Clause</p>
                      <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 italic text-slate-700 font-medium leading-relaxed">
                        "{clause.clauseText}"
                      </div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-8 pt-4 border-t border-slate-50">
                      <div className="space-y-3">
                        <div className="flex items-center gap-2 text-blue-600">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                          <h6 className="font-bold text-slate-900">{t.analysis}</h6>
                        </div>
                        <p className="text-slate-600 text-sm leading-relaxed">{clause.analysis}</p>
                      </div>
                      <div className="space-y-3">
                        <div className="flex items-center gap-2 text-emerald-600">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                          <h6 className="font-bold text-slate-900">{t.recommendation}</h6>
                        </div>
                        <p className="text-slate-600 text-sm leading-relaxed">{clause.recommendation}</p>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {savedAnalyses.length > 0 && (
          <div className="mt-20 space-y-6">
            <div className="flex items-center gap-3 px-2">
              <h3 className="font-black text-slate-400 uppercase tracking-widest text-xs">Secure Local Archives</h3>
              <div className="flex-1 h-px bg-slate-200"></div>
            </div>
            <div className="grid sm:grid-cols-2 gap-4">
              {savedAnalyses.map((item) => (
                <div key={item.id} className="bg-white border border-slate-200 rounded-3xl p-6 hover:shadow-xl hover:-translate-y-1 transition-all group">
                  <div className="flex items-start justify-between mb-8">
                    <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors">
                      <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M18 8h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zM9 6c0-1.66 1.34-3 3-3s3 1.34 3 3v2H9V6z"/></svg>
                    </div>
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-tighter">
                      {new Date(item.timestamp).toLocaleDateString()}
                    </span>
                  </div>
                  <div className="space-y-1 mb-6">
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Analysis Record</p>
                    <p className="font-bold text-slate-800 truncate">{new Date(item.timestamp).toLocaleTimeString()}</p>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" onClick={() => loadSavedAnalysis(item)} className="flex-1">Unlock</Button>
                    <Button size="sm" variant="ghost" onClick={() => deleteSaved(item.id)} className="text-red-400 hover:text-red-600 hover:bg-red-50">Delete</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-100 py-12 mt-20">
        <div className="max-w-4xl mx-auto px-4 text-center space-y-6">
          <div className="flex justify-center gap-8 opacity-40">
            <span className="text-[10px] font-black tracking-widest uppercase">Privacy First</span>
            <span className="text-[10px] font-black tracking-widest uppercase">POPIA Ready</span>
            <span className="text-[10px] font-black tracking-widest uppercase">AES-256 GCM</span>
          </div>
          <p className="text-xs text-slate-400 leading-relaxed max-w-sm mx-auto">
            ContractCheck is an educational risk assessment tool. Always seek professional legal counsel.
          </p>
          <p className="text-[10px] font-bold text-slate-300">© {new Date().getFullYear()} ContractCheck SA</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Language, AnalysisResult, SavedAnalysis } from './types';
import { TRANSLATIONS } from './constants';
import { parsePDF } from './services/pdfService';
import { analyzeContract } from './services/geminiService';
import { encryptData, decryptData } from './services/cryptoService';
import Button from './components/Button';
import Badge from './components/Badge';
import Onboarding from './components/Onboarding';
import RiskGauge from './components/RiskGauge';

const SAMPLE_CONTRACT = `
LEASE AGREEMENT
1. PARTIES: Landlord (Smith) and Tenant (Jones).
2. DEPOSIT: Tenant shall pay a deposit of R10,000. Landlord may retain the entire deposit for any reason at their sole discretion at the end of the lease, regardless of the condition of the property.
3. ACCESS: Landlord may enter the premises at any time of day or night without prior notice to the Tenant for any reason.
4. LIABILITY: The Tenant waives all rights to claim damages from the Landlord for any injury occurring on the property, even if caused by the Landlord's gross negligence or intentional failure to maintain the structure.
5. TERMINATION: The Landlord may terminate this lease with 24 hours' notice if they decide to sell the property. The Tenant must vacate immediately.
6. POPIA: Tenant hereby grants Landlord permission to sell Tenant's personal data, including credit records and identity numbers, to any third-party marketing company without further consent.
`;

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [savedAnalyses, setSavedAnalyses] = useState<SavedAnalysis[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [originalFile, setOriginalFile] = useState<File | null>(null);

  const t = TRANSLATIONS[lang];
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);

    const saved = JSON.parse(localStorage.getItem('contractcheck_saved') || '[]');
    setSavedAnalyses(saved);

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processText = async (text: string) => {
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setProgress(30);
    setLoadingText('Analyzing risk factors with AI...');

    try {
      const progressInterval = setInterval(() => {
        setProgress(prev => (prev < 90 ? prev + 5 : prev));
      }, 1000);

      const result = await analyzeContract(text);
      clearInterval(progressInterval);
      setProgress(100);
      setAnalysis(result);
    } catch (err: any) {
      setError(err.message || 'Analysis failed. This could be due to complex content or connectivity.');
    } finally {
      setTimeout(() => {
        setLoading(false);
        setLoadingText('');
        setProgress(0);
      }, 500);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | undefined;

    if ('target' in e && 'files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e) {
      e.preventDefault();
      setIsDragging(false);
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError('Please upload a valid PDF document.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('File too large. Max allowed size is 10MB.');
      return;
    }

    setOriginalFile(file);
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setProgress(5);
    setLoadingText('Parsing PDF document structure...');

    try {
      const text = await parsePDF(file);
      setProgress(20);
      await processText(text);
    } catch (err: any) {
      setError(err.message || 'Failed to read PDF. The file might be corrupted or protected.');
      setLoading(false);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const loadSample = () => {
    setOriginalFile(null);
    processText(SAMPLE_CONTRACT);
  };

  const downloadOriginal = () => {
    if (!originalFile) return;
    const url = URL.createObjectURL(originalFile);
    const a = document.createElement('a');
    a.href = url;
    a.download = originalFile.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const printReport = () => {
    window.print();
  };

  const saveAnalysis = async () => {
    if (!analysis) return;
    const password = prompt('Secure your data. Set a password to encrypt this analysis:');
    if (!password) return;

    setIsSaving(true);
    try {
      const encrypted = await encryptData(analysis, password);
      const newSaved: SavedAnalysis = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        encrypted
      };
      const updatedList = [newSaved, ...savedAnalyses];
      setSavedAnalyses(updatedList);
      localStorage.setItem('contractcheck_saved', JSON.stringify(updatedList));
    } catch (err) {
      alert('Encryption process failed.');
    } finally {
      setIsSaving(false);
    }
  };

  const loadSavedAnalysis = async (item: SavedAnalysis) => {
    const password = prompt('Enter the decryption password for this record:');
    if (!password) return;

    try {
      const decrypted = await decryptData(item.encrypted, password);
      setAnalysis(decrypted);
      setError(null);
      setOriginalFile(null); // Clear original file as it's a historical record
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      alert('Incorrect password or record integrity check failed.');
    }
  };

  const deleteSaved = (id: number) => {
    if (!confirm('Permanently delete this record?')) return;
    const updated = savedAnalyses.filter(a => a.id !== id);
    setSavedAnalyses(updated);
    localStorage.setItem('contractcheck_saved', JSON.stringify(updated));
  };

  const closeOnboarding = (dontShow: boolean) => {
    if (dontShow) localStorage.setItem('contractcheck_onboarding_seen', 'true');
    setShowOnboarding(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col antialiased">
      {showOnboarding && <Onboarding onClose={closeOnboarding} />}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 no-print">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-blue-200 shadow-lg">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-900 leading-tight">ContractCheck</h1>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">SA Risk Intelligence</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <select 
                value={lang} 
                onChange={(e) => setLang(e.target.value as Language)}
                className="hidden sm:block bg-slate-100 text-slate-700 text-sm font-semibold px-3 py-2 rounded-lg border-none outline-none focus:ring-2 focus:ring-blue-100 cursor-pointer"
              >
                <option value="en">English</option>
                <option value="af">Afrikaans</option>
                <option value="zu">isiZulu</option>
              </select>
              <button 
                onClick={() => setShowOnboarding(true)}
                className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
                title="Help & Info"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              </button>
              <div className={`hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${isOnline ? 'border-emerald-100 bg-emerald-50 text-emerald-700' : 'border-red-100 bg-red-50 text-red-700'}`}>
                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isOnline ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
                <span className="text-[10px] font-bold tracking-tight">{isOnline ? 'LIVE' : 'OFFLINE'}</span>
              </div>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full px-4 sm:px-6 py-10">

        {!isOnline && (
          <div className="mb-8 p-4 bg-amber-50 border border-amber-200 rounded-2xl flex gap-3 items-start fade-in shadow-sm no-print">
            <svg className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            <p className="text-sm text-amber-800 font-medium">Limited functionality. Connect to the internet for AI analysis.</p>
          </div>
        )}

        {!analysis && !loading && (
          <div className="space-y-8 no-print">
            <div className="text-center space-y-3">
              <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">Contract Triage</h2>
              <p className="text-slate-500 max-w-lg mx-auto leading-relaxed">
