              <Button variant="ghost" size="sm" onClick={() => setIsComparing(false)}>Close</Button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 sm:p-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
                {selectedClauseIndices.map((idx) => {
                  const clause = adjustedAnalysis.flaggedClauses[idx];
                  return (
                    <div key={idx} className="space-y-6 flex flex-col">
                      <div className="flex justify-between items-start">
                        <h3 className="text-lg font-bold">{clause.issue}</h3>
                        <Badge level={clause.riskLevel} label={t[`${clause.riskLevel}Risk` as keyof typeof t]} />
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 italic text-sm text-slate-700 leading-relaxed min-h-[100px]">
                        "{clause.clauseText}"
                      </div>
                      <div className="space-y-4">
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Analysis</p>
                          <p className="text-sm text-slate-600 leading-relaxed">{clause.analysis}</p>
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Recommendation</p>
                          <p className="text-sm text-slate-600 leading-relaxed">{clause.recommendation}</p>
                        </div>
                      </div>
                    </div>
