                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {savedAnalyses.length > 0 && !adjustedAnalysis && !loading && (
          <div className="mt-20 space-y-8 no-print fade-in">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest text-center">Encrypted Local Archives</h3>
            <div className="grid sm:grid-cols-2 gap-6">
              {savedAnalyses.map((item) => (
