                    <Button size="md" onClick={() => loadSavedAnalysis(item)} className="flex-1">Unlock Archive</Button>
                    <Button size="md" variant="ghost" onClick={() => deleteSaved(item.id)} className="text-red-400 hover:bg-red-50">Delete</Button>
                  </div>
