          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-100 py-16 mt-auto no-print">
        <div className="max-w-4xl mx-auto px-4 text-center space-y-8">
          <div className="flex flex-wrap justify-center gap-x-12 gap-y-4 opacity-30">
            <span className="text-[10px] font-black tracking-widest uppercase">Privacy Obsessed</span>
            <span className="text-[10px] font-black tracking-widest uppercase">CPA & POPIA Context</span>
            <span className="text-[10px] font-black tracking-widest uppercase">AES-256 GCM Vault</span>
