import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Language, AnalysisResult, SavedAnalysis, RiskLevel, RiskThresholds, FlaggedClause } from './types';
import { TRANSLATIONS, PRE_ANALYZED_SAMPLE } from './constants';
import { parsePDF } from './services/pdfService';
import { analyzeContract } from './services/geminiService';
import { encryptData, decryptData } from './services/cryptoService';
import Button from './components/Button';
import Badge from './components/Badge';
import Onboarding from './components/Onboarding';
import RiskGauge from './components/RiskGauge';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [savedAnalyses, setSavedAnalyses] = useState<SavedAnalysis[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [originalFile, setOriginalFile] = useState<File | null>(null);

  // New features state
  const [thresholds, setThresholds] = useState<RiskThresholds>({ lowMax: 30, mediumMax: 70 });
  const [selectedClauseIndices, setSelectedClauseIndices] = useState<number[]>([]);
  const [isComparing, setIsComparing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const t = TRANSLATIONS[lang];
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);

    const saved = JSON.parse(localStorage.getItem('contractcheck_saved') || '[]');
    setSavedAnalyses(saved);

    const localThresholds = localStorage.getItem('contractcheck_thresholds');
    if (localThresholds) setThresholds(JSON.parse(localThresholds));

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const getLevel = (score: number, thresh: RiskThresholds): RiskLevel => {
    if (score <= thresh.lowMax) return 'low';
    if (score <= thresh.mediumMax) return 'medium';
    return 'high';
  };

  const adjustedAnalysis = useMemo(() => {
    if (!analysis) return null;
    return {
      ...analysis,
      overallRisk: getLevel(analysis.overallRiskScore, thresholds),
      flaggedClauses: analysis.flaggedClauses.map(c => ({
        ...c,
        riskLevel: getLevel(c.riskScore, thresholds)
      }))
    };
  }, [analysis, thresholds]);

  const processText = async (text: string) => {
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setSelectedClauseIndices([]);
    setProgress(30);
    setLoadingText('Analyzing risk factors with AI...');

    try {
      const progressInterval = setInterval(() => {
        setProgress(prev => (prev < 90 ? prev + 5 : prev));
      }, 1000);

      const result = await analyzeContract(text);
      clearInterval(progressInterval);
      setProgress(100);
      setAnalysis(result);
    } catch (err: any) {
      setError(err.message || 'Analysis failed. This could be due to complex content or connectivity.');
    } finally {
      setTimeout(() => {
        setLoading(false);
        setLoadingText('');
        setProgress(0);
      }, 500);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | undefined;

    if ('target' in e && 'files' in (e.target as any) && (e.target as any).files) {
      file = (e.target as any).files[0];
    } else if ('dataTransfer' in e) {
      e.preventDefault();
      setIsDragging(false);
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError('Please upload a valid PDF document.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('File too large. Max allowed size is 10MB.');
      return;
    }

    setOriginalFile(file);
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setProgress(5);
    setLoadingText('Parsing PDF document structure...');

    try {
      const text = await parsePDF(file);
      setProgress(20);
      await processText(text);
    } catch (err: any) {
      setError(err.message || 'Failed to read PDF. The file might be corrupted or protected.');
      setLoading(false);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const loadSample = () => {
    setOriginalFile(null);
    setAnalysis(PRE_ANALYZED_SAMPLE);
    setSelectedClauseIndices([]);
    setError(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const downloadOriginal = () => {
    if (!originalFile) return;
    const url = URL.createObjectURL(originalFile);
    const a = document.createElement('a');
    a.href = url;
    a.download = originalFile.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const exportAsText = () => {
    if (!adjustedAnalysis) return;
    let content = `CONTRACT RISK ANALYSIS REPORT\n`;
    content += `Date: ${new Date().toLocaleString()}\n`;
    content += `Overall Risk Level: ${adjustedAnalysis.overallRisk.toUpperCase()} (Score: ${adjustedAnalysis.overallRiskScore})\n\n`;
    content += `FLAGGED CLAUSES:\n`;
    adjustedAnalysis.flaggedClauses.forEach((c, idx) => {
      content += `${idx + 1}. ISSUE: ${c.issue}\n`;
      content += `   RISK: ${c.riskLevel.toUpperCase()} (Score: ${c.riskScore})\n`;
      content += `   CLAUSE: "${c.clauseText}"\n`;
      content += `   ANALYSIS: ${c.analysis}\n`;
      content += `   RECOMMENDATION: ${c.recommendation}\n\n`;
    });

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'contract_analysis.txt';
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportAsJSON = () => {
    if (!adjustedAnalysis) return;
    const blob = new Blob([JSON.stringify(adjustedAnalysis, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'contract_analysis.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const toggleClauseSelection = (idx: number) => {
    setSelectedClauseIndices(prev => {
      if (prev.includes(idx)) return prev.filter(i => i !== idx);
      if (prev.length >= 2) return [prev[1], idx];
      return [...prev, idx];
    });
  };

  const saveThresholds = (newThresh: RiskThresholds) => {
    setThresholds(newThresh);
    localStorage.setItem('contractcheck_thresholds', JSON.stringify(newThresh));
  };

  const saveAnalysis = async () => {
    if (!analysis) return;
    const password = prompt('Secure your data. Set a password to encrypt this analysis:');
    if (!password) return;

    setIsSaving(true);
    try {
      const encrypted = await encryptData(analysis, password);
      const newSaved: SavedAnalysis = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        encrypted
      };
      const updatedList = [newSaved, ...savedAnalyses];
      setSavedAnalyses(updatedList);
      localStorage.setItem('contractcheck_saved', JSON.stringify(updatedList));
      alert("Analysis saved securely to local vault.");
    } catch (err) {
      alert('Encryption process failed.');
    } finally {
      setIsSaving(false);
    }
  };

  const loadSavedAnalysis = async (item: SavedAnalysis) => {
    const password = prompt('Enter the decryption password for this record:');
    if (!password) return;

    try {
      const decrypted = await decryptData(item.encrypted, password);
      setAnalysis(decrypted);
      setError(null);
      setOriginalFile(null);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      alert('Incorrect password or record integrity check failed.');
    }
  };

  const deleteSaved = (id: number) => {
    if (!confirm('Permanently delete this record?')) return;
    const updated = savedAnalyses.filter(a => a.id !== id);
    setSavedAnalyses(updated);
    localStorage.setItem('contractcheck_saved', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col antialiased">
      {showOnboarding && <Onboarding onClose={(ds) => {
        if (ds) localStorage.setItem('contractcheck_onboarding_seen', 'true');
        setShowOnboarding(false);
      }} />}

      {/* Comparison Modal Overlay */}
      {isComparing && adjustedAnalysis && (
        <div className="fixed inset-0 z-[60] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-4 sm:p-8 fade-in">
          <div className="bg-white w-full max-w-6xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold">Side-by-Side Clause Comparison</h2>
              <Button variant="ghost" size="sm" onClick={() => setIsComparing(false)}>Close</Button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 sm:p-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
                {selectedClauseIndices.map((idx) => {
                  const clause = adjustedAnalysis.flaggedClauses[idx];
                  return (
                    <div key={idx} className="space-y-6 flex flex-col">
                      <div className="flex justify-between items-start">
                        <h3 className="text-lg font-bold text-slate-900">{clause.issue}</h3>
                        <Badge level={clause.riskLevel} label={t[`${clause.riskLevel}Risk` as keyof typeof t]} />
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 italic text-sm text-slate-700 leading-relaxed min-h-[100px]">
                        "{clause.clauseText}"
                      </div>
                      <div className="space-y-4">
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Analysis</p>
                          <p className="text-sm text-slate-600 leading-relaxed">{clause.analysis}</p>
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Recommendation</p>
                          <p className="text-sm text-slate-600 leading-relaxed">{clause.recommendation}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 no-print">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-blue-200 shadow-lg">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-900 leading-tight">ContractCheck</h1>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">SA Risk Intelligence</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <div className="flex items-center bg-slate-100 rounded-lg p-1 mr-2 border border-slate-200">
                {(['en', 'af', 'zu'] as Language[]).map((l) => (
                  <button
                    key={l}
                    onClick={() => setLang(l)}
                    className={`px-2 py-1 text-[10px] font-black uppercase tracking-widest rounded-md transition-all ${lang === l ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    {l}
                  </button>
                ))}
              </div>
              <Button 
                variant="ghost" 
                size="sm" 
                onClick={() => setShowSettings(!showSettings)}
                className={showSettings ? "bg-slate-100" : ""}
                icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>}
              >
                Settings
              </Button>
              <div className={`hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${isOnline ? 'border-emerald-100 bg-emerald-50 text-emerald-700' : 'border-red-100 bg-red-50 text-red-700'}`}>
                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isOnline ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
                <span className="text-[10px] font-bold tracking-tight">{isOnline ? 'LIVE' : 'OFFLINE'}</span>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Threshold Settings Panel */}
      {showSettings && (
        <div className="bg-white border-b border-slate-200 p-6 no-print fade-in">
          <div className="max-w-4xl mx-auto space-y-4">
            <h3 className="text-sm font-bold text-slate-900 uppercase tracking-widest">Risk Sensitivity Settings</h3>
            <p className="text-xs text-slate-500">Adjust the numerical thresholds that define risk categories. Changes apply instantly to your current analysis results.</p>
            <div className="flex flex-col sm:flex-row gap-8 pt-2">
              <div className="flex-1 space-y-2">
                <label className="flex justify-between text-xs font-bold text-slate-700">
                  <span>Low Risk Cut-off</span>
                  <span className="text-emerald-600">0 - {thresholds.lowMax}</span>
                </label>
                <input 
                  type="range" min="5" max="50" value={thresholds.lowMax} 
                  onChange={(e) => saveThresholds({ ...thresholds, lowMax: parseInt(e.target.value) })}
                  className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-emerald-500" 
                />
              </div>
              <div className="flex-1 space-y-2">
                <label className="flex justify-between text-xs font-bold text-slate-700">
                  <span>Medium Risk Cut-off</span>
                  <span className="text-amber-600">{thresholds.lowMax + 1} - {thresholds.mediumMax}</span>
                </label>
                <input 
                  type="range" min={thresholds.lowMax + 5} max="90" value={thresholds.mediumMax} 
                  onChange={(e) => saveThresholds({ ...thresholds, mediumMax: parseInt(e.target.value) })}
                  className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-amber-500" 
                />
              </div>
              <div className="flex-1 space-y-2">
                <label className="flex justify-between text-xs font-bold text-slate-700">
                  <span>High Risk Range</span>
                  <span className="text-red-600">{thresholds.mediumMax + 1} - 100</span>
                </label>
                <div className="h-1.5 bg-red-100 rounded-full w-full"></div>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-4xl mx-auto w-full px-4 sm:px-6 py-10">

        {!isOnline && (
          <div className="mb-8 p-4 bg-amber-50 border border-amber-200 rounded-2xl flex gap-3 items-start fade-in shadow-sm no-print">
            <svg className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            <p className="text-sm text-amber-800 font-medium">Limited functionality. Connect to the internet for AI analysis.</p>
          </div>
        )}

        {!adjustedAnalysis && !loading && (
          <div className="space-y-8 no-print">
            <div className="text-center space-y-3">
              <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">Contract Triage</h2>
              <p className="text-slate-500 max-w-lg mx-auto leading-relaxed">
                Upload a South African legal document or try our instant sample to explore risk analysis.
              </p>
            </div>

            <div 
              className={`relative group transition-all duration-300 ${isDragging ? 'scale-[1.02]' : ''}`}
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={handleFileUpload}
            >
              <div className={`absolute -inset-1 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-3xl blur opacity-10 transition duration-500 ${isDragging ? 'opacity-30' : 'group-hover:opacity-20'}`}></div>
              <div className={`relative border-2 border-dashed rounded-3xl p-16 bg-white transition-all text-center ${isDragging ? 'border-blue-500 bg-blue-50 shadow-2xl' : 'border-slate-200 hover:border-blue-400 hover:shadow-xl'}`}>
                <input 
                  type="file" 
                  accept=".pdf" 
                  ref={fileInputRef}
                  onChange={handleFileUpload} 
                  className="absolute inset-0 opacity-0 cursor-pointer z-10"
                />
                <div className="space-y-6">
                  <div className={`w-20 h-20 rounded-2xl flex items-center justify-center mx-auto transition-all ${isDragging ? 'bg-blue-600 text-white scale-110' : 'bg-blue-50 text-blue-600 group-hover:scale-110'}`}>
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-900">{isDragging ? 'Drop to start analysis' : 'Drop your contract PDF here'}</h3>
                    <p className="text-slate-400 text-sm mt-2">Maximum file size: 10MB</p>
                  </div>
                  <div className="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">
                    <Button size="md" className="pointer-events-none w-full sm:w-auto">Select File</Button>
                    <span className="text-slate-300 text-xs font-bold uppercase">or</span>
                    <Button variant="ghost" size="md" onClick={loadSample} className="w-full sm:w-auto relative z-20">Instant Sample Review</Button>
                  </div>
                </div>
              </div>
            </div>

            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-600 text-sm font-semibold flex items-center gap-3 fade-in">
                <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                {error}
              </div>
            )}
          </div>
        )}

        {loading && (
          <div className="py-24 text-center space-y-10 fade-in no-print">
            <div className="max-w-md mx-auto space-y-4">
              <div className="relative inline-flex mb-4">
                <div className="w-24 h-24 rounded-3xl border-4 border-blue-50 animate-pulse"></div>
                <div className="absolute inset-0 w-24 h-24 rounded-3xl border-4 border-blue-600 border-t-transparent animate-spin"></div>
              </div>
              <div className="space-y-1">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">{loadingText}</h3>
                <p className="text-slate-400 font-medium">Please wait while our engine reviews legal clauses...</p>
              </div>

              <div className="relative pt-6">
                <div className="flex mb-2 items-center justify-between">
                  <div>
                    <span className="text-xs font-black inline-block py-1 px-2 uppercase rounded-full text-blue-600 bg-blue-100">
                      Processing
                    </span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-bold inline-block text-blue-600">
                      {progress}%
                    </span>
                  </div>
                </div>
                <div className="overflow-hidden h-3 mb-4 text-xs flex rounded-full bg-slate-100">
                  <div 
                    style={{ width: `${progress}%` }} 
                    className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-blue-600 transition-all duration-500 ease-out"
                  ></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {adjustedAnalysis && (
          <div className="fade-in space-y-10 pb-20">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white p-4 rounded-2xl shadow-sm border border-slate-100 action-bar no-print">
               <div className="flex gap-2">
                <Button variant="ghost" size="sm" onClick={() => { setAnalysis(null); setError(null); setOriginalFile(null); setSelectedClauseIndices([]); }} icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"/></svg>}>
                  Back
                </Button>
                {selectedClauseIndices.length === 2 && (
                  <Button variant="primary" size="sm" onClick={() => setIsComparing(true)}>
                    Compare Selected
                  </Button>
                )}
               </div>
              <div className="flex flex-wrap gap-2 w-full sm:w-auto justify-end">
                {originalFile && (
                  <Button size="sm" variant="secondary" onClick={downloadOriginal} title="Download the original PDF file">
                    Original PDF
                  </Button>
                )}
                <div className="flex gap-1">
                  <Button size="sm" variant="secondary" onClick={() => window.print()} title="Export the risk report as a PDF document">
                    PDF
                  </Button>
                  <Button size="sm" variant="secondary" onClick={exportAsText} title="Export analysis as a plain text file">
                    TXT
                  </Button>
                  <Button size="sm" variant="secondary" onClick={exportAsJSON} title="Export analysis as structured JSON data">
                    JSON
                  </Button>
                </div>
                <Button size="sm" onClick={saveAnalysis} loading={isSaving} icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4"/></svg>}>
                  Save to Vault
                </Button>
              </div>
            </div>

            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden flex flex-col md:flex-row">
              <div className="p-10 flex flex-col items-center justify-center bg-slate-50 border-b md:border-b-0 md:border-r border-slate-100 min-w-[200px]">
                <RiskGauge score={adjustedAnalysis.overallRiskScore} level={adjustedAnalysis.overallRisk} label={t[`${adjustedAnalysis.overallRisk}Risk` as keyof typeof t]} />
              </div>
              <div className="p-10 flex-1">
                <h3 className="text-2xl font-black text-slate-900 mb-4">{t.overallRisk}</h3>
                <p className="text-slate-600 leading-relaxed mb-6">
                  {adjustedAnalysis.flaggedClauses.length > 0 
                    ? `AI analysis identified ${adjustedAnalysis.flaggedClauses.length} clauses that may pose legal risks. Risk levels are dynamically categorized based on your sensitivity settings.`
                    : t.noIssues}
                </p>
                {adjustedAnalysis.uncertainty && (
                  <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 text-sm text-blue-700 font-medium italic">
                    <span className="font-bold uppercase tracking-wider text-[10px] block mb-1">Expert Note</span>
                    {adjustedAnalysis.uncertainty}
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h4 className="font-black text-slate-900 uppercase tracking-widest text-xs">Identified Liabilities</h4>
                <p className="text-[10px] text-slate-400 font-bold uppercase">Select 2 to Compare</p>
              </div>

              {adjustedAnalysis.flaggedClauses.map((clause, idx) => (
                <div 
                  key={idx} 
                  className={`relative bg-white rounded-3xl border-2 transition-all overflow-hidden group cursor-pointer ${selectedClauseIndices.includes(idx) ? 'border-blue-500 shadow-lg' : 'border-slate-100 shadow-sm hover:border-slate-200'}`}
                  onClick={() => toggleClauseSelection(idx)}
                >
                  {selectedClauseIndices.includes(idx) && (
                    <div className="absolute top-4 right-4 z-10 w-6 h-6 bg-blue-600 rounded-full flex items-center justify-center text-white">
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>
                    </div>
                  )}
                  <div className={`h-2 ${clause.riskLevel === 'high' ? 'bg-red-500' : clause.riskLevel === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                  <div className="p-8 space-y-6">
                    <div className="flex justify-between items-start gap-4">
                      <div>
                        <h5 className="text-xl font-bold text-slate-900 mb-1">{clause.issue}</h5>
                        <div className="flex gap-2 items-center">
                          <Badge level={clause.riskLevel} label={t[`${clause.riskLevel}Risk` as keyof typeof t]} />
                          <span className="text-[10px] font-bold text-slate-400 tracking-tighter">Score: {Math.round(clause.riskScore)}</span>
                        </div>
                      </div>
                    </div>

