const JargonText: React.FC<{ text: string }> = ({ text }) => {
  const parts = text.split(/(\b(?:POPIA|CPA|BCEA|LRA|RHA)\b)/g);
  return (
    <>
      {parts.map((part, i) => {
        const explanation = JARGON_EXPLANATIONS[part];
        if (explanation) {
          return (
            <span key={i} className="relative group cursor-help border-b border-dotted border-blue-400 text-blue-700 font-semibold">
              {part}
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 p-2 bg-slate-800 text-white text-[10px] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50 shadow-xl">
                {explanation}
              </span>
            </span>
          );
        }
        return part;
      })}
    </>
  );
};

