import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Language, AnalysisResult, RiskLevel, RiskThresholds, FlaggedClause, ExportOptions } from './types';
import { TRANSLATIONS, PRE_ANALYZED_SAMPLES, JARGON_EXPLANATIONS } from './constants';
import { parsePDF } from './services/pdfService';
import { analyzeContract } from './services/geminiService';
import Button from './components/Button';
import Badge from './components/Badge';
import Onboarding from './components/Onboarding';
import RiskGauge from './components/RiskGauge';

const JargonText: React.FC<{ text: string }> = ({ text }) => {
  const jargonKeys = Object.keys(JARGON_EXPLANATIONS);
  const regex = new RegExp(`(\\b(?:${jargonKeys.join('|')})\\b)`, 'g');
  const parts = text.split(regex);

  return (
    <>
      {parts.map((part, i) => {
        const explanation = JARGON_EXPLANATIONS[part];
        if (explanation) {
          return (
            <span key={i} className="relative group cursor-help border-b-2 border-dotted border-blue-400/50 text-blue-700 font-bold px-0.5 hover:bg-blue-50 transition-colors rounded-sm">
              {part}
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 w-64 p-4 bg-slate-900/95 backdrop-blur-sm text-white text-[11px] rounded-2xl opacity-0 group-hover:opacity-100 transition-all pointer-events-none z-[100] shadow-2xl leading-relaxed scale-95 group-hover:scale-100 origin-bottom">
                <span className="block font-black mb-2 border-b border-slate-700 pb-1 text-blue-300 uppercase tracking-widest">{part} Definition</span>
                {explanation}
              </span>
            </span>
          );
        }
        return part;
      })}
    </>
  );
};

const DocumentContextView: React.FC<{ 
  text: string, 
  clauses: FlaggedClause[], 
  hoveredIndex: number | null, 
  onHover: (idx: number | null) => void,
  onScrollTo: (idx: number) => void
}> = ({ text, clauses, hoveredIndex, onHover, onScrollTo }) => {
  if (!text) return null;

  let content: React.ReactNode[] = [text];

  clauses.forEach((clause, idx) => {
    const newContent: React.ReactNode[] = [];
    content.forEach((item) => {
      if (typeof item !== 'string') {
        newContent.push(item);
        return;
      }

      const parts = item.split(clause.clauseText);
      parts.forEach((part, i) => {
        newContent.push(part);
        if (i < parts.length - 1) {
          const riskColors = {
            high: 'bg-red-100 text-red-900 border-red-200',
            medium: 'bg-amber-100 text-amber-900 border-amber-200',
            low: 'bg-emerald-100 text-emerald-900 border-emerald-200'
          };

          newContent.push(
            <mark
              key={`${idx}-${i}`}
              onMouseEnter={() => onHover(idx)}
              onMouseLeave={() => onHover(null)}
              onClick={() => onScrollTo(idx)}
              className={`px-1 rounded-md border cursor-pointer transition-all duration-300 ${
                riskColors[clause.riskLevel]
              } ${hoveredIndex === idx ? 'ring-4 ring-blue-500/30 scale-[1.02] shadow-lg z-10' : 'opacity-80 hover:opacity-100'}`}
            >
              {clause.clauseText}
              <span className="ml-1 text-[8px] font-black uppercase align-top bg-white/50 px-1 rounded-sm">Issue #{idx + 1}</span>
            </mark>
          );
        }
      });
    });
    content = newContent;
  });

  return (
    <div className="bg-white border border-slate-200 rounded-[2.5rem] p-10 shadow-inner overflow-y-auto max-h-[70vh] custom-scrollbar text-sm leading-relaxed text-slate-500 font-medium whitespace-pre-wrap">
      <div className="sticky top-0 bg-white/90 backdrop-blur-md -mt-10 -mx-10 p-6 border-b border-slate-100 mb-6 z-20 flex justify-between items-center">
        <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Document Source Context</h4>
        <div className="flex gap-2">
          <div className="w-2 h-2 rounded-full bg-red-400"></div>
          <div className="w-2 h-2 rounded-full bg-amber-400"></div>
          <div className="w-2 h-2 rounded-full bg-emerald-400"></div>
        </div>
      </div>
      {content}
    </div>
  );
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [rawText, setRawText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [thresholds, setThresholds] = useState<RiskThresholds>({ lowMax: 30, mediumMax: 70 });
  const [selectedIndices, setSelectedIndices] = useState<number[]>([]);
  const [isComparing, setIsComparing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [activeHighlight, setActiveHighlight] = useState<number | null>(null);
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [privateNotes, setPrivateNotes] = useState<Record<number, string>>({});
  const [exportConfig, setExportConfig] = useState<ExportOptions>({
    includeClauses: true,
    includeContext: false,
    includeScores: true,
    includeNotes: true,
    includeRecommendations: true
  });

  const t = TRANSLATIONS[lang];
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);
    const localThresholds = localStorage.getItem('contractcheck_thresholds');
    if (localThresholds) setThresholds(JSON.parse(localThresholds));
  }, []);

  const getLevel = (score: number, thresh: RiskThresholds): RiskLevel => {
    if (score <= thresh.lowMax) return 'low';
    if (score <= thresh.mediumMax) return 'medium';
    return 'high';
  };

  const adjustedAnalysis = useMemo(() => {
    if (!analysis) return null;
    return {
      ...analysis,
      overallRisk: getLevel(analysis.overallRiskScore, thresholds),
      flaggedClauses: analysis.flaggedClauses.map((c, idx) => ({
        ...c,
        riskLevel: getLevel(c.riskScore, thresholds),
        privateNote: privateNotes[idx] || ''
      }))
    };
  }, [analysis, thresholds, privateNotes]);

  const processText = async (text: string) => {
    setLoading(true); setError(null); setAnalysis(null); setRawText(text); setProgress(30);
    setLoadingText('Analyzing risk factors with AI...');
    try {
      const result = await analyzeContract(text);
      setAnalysis(result);
      setPrivateNotes({});
    } catch (err: any) {
      setError(err.message || 'Analysis failed. Please try again.');
    } finally {
      setLoading(false); setProgress(0);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | undefined;
    if ('dataTransfer' in e) {
      e.preventDefault(); e.stopPropagation(); setIsDragging(false);
      file = e.dataTransfer.files[0];
    } else {
      file = e.target.files?.[0];
    }
    if (!file) return;
    if (file.type !== 'application/pdf') {
      setError('Unsupported file type. Please upload a PDF contract.');
      return;
    }

    setLoading(true); setProgress(5); setLoadingText('Parsing Document...');
    try {
      const text = await parsePDF(file);
      setProgress(20); await processText(text);
    } catch (err: any) {
      setError('Failed to process PDF.'); setLoading(false);
    }
  };

  const loadSample = (key: string) => {
    setAnalysis(PRE_ANALYZED_SAMPLES[key]);
    setRawText(`This is a sample document for ${key}.\n\n` + PRE_ANALYZED_SAMPLES[key].flaggedClauses.map(c => c.clauseText).join('\n\n') + '\n\nEnd of sample.');
    setPrivateNotes({});
    setSelectedIndices([]);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToClause = (idx: number) => {
    setActiveHighlight(idx);
    cardRefs.current[idx]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setTimeout(() => setActiveHighlight(null), 3000);
  };

  const toggleSelection = (idx: number) => {
    setSelectedIndices(prev => {
      if (prev.includes(idx)) return prev.filter(i => i !== idx);
      if (prev.length < 2) return [...prev, idx];
      return [prev[1], idx];
    });
  };

  const handleNoteChange = (idx: number, note: string) => {
    setPrivateNotes(prev => ({ ...prev, [idx]: note }));
  };

  const executeExport = () => {
    if (!adjustedAnalysis) return;

    let report = `CONTRACTCHECK RISK REPORT\nGenerated: ${new Date().toLocaleString()}\n`;
    report += `Overall Risk: ${adjustedAnalysis.overallRisk.toUpperCase()} (Score: ${adjustedAnalysis.overallRiskScore})\n\n`;

    if (exportConfig.includeContext) {
      report += `DOCUMENT CONTEXT:\n${rawText.substring(0, 1000)}...\n\n`;
    }

    report += `FLAGGED CLAUSES:\n${'='.repeat(20)}\n\n`;

    adjustedAnalysis.flaggedClauses.forEach((c, i) => {
      report += `[ISSUE #${i + 1}] ${c.issue}\n`;
      if (exportConfig.includeScores) report += `Risk Level: ${c.riskLevel.toUpperCase()} (Score: ${c.riskScore})\n`;
      if (exportConfig.includeClauses) report += `Clause: "${c.clauseText}"\n`;
      report += `Analysis: ${c.analysis}\n`;
      if (exportConfig.includeRecommendations) report += `Recommendation: ${c.recommendation}\n`;
      if (exportConfig.includeNotes && c.privateNote) report += `Private User Note: ${c.privateNote}\n`;
      report += `\n`;
    });

    const blob = new Blob([report], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `contractcheck_report_${Date.now()}.txt`;
    a.click();
    setShowExportModal(false);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col antialiased text-slate-900 selection:bg-blue-100 selection:text-blue-900">
      {showOnboarding && <Onboarding onClose={(ds) => { if (ds) localStorage.setItem('contractcheck_onboarding_seen', 'true'); setShowOnboarding(false); }} />}

      {/* Export Config Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[110] bg-slate-950/40 backdrop-blur-md flex items-center justify-center p-6 fade-in">
          <div className="bg-white rounded-[3rem] shadow-3xl max-w-md w-full p-10 border border-slate-100">
            <h3 className="text-2xl font-black text-slate-900 mb-2">Export Config</h3>
            <p className="text-slate-500 text-sm mb-8 font-medium">Customize your analysis report content.</p>

