import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Language, AnalysisResult, RiskLevel, RiskThresholds, FlaggedClause, ExportOptions } from './types';
import { TRANSLATIONS, PRE_ANALYZED_SAMPLES, JARGON_EXPLANATIONS } from './constants';
import { parsePDF } from './services/pdfService';
import { analyzeContract } from './services/geminiService';
import Button from './components/Button';
import Badge from './components/Badge';
import Onboarding from './components/Onboarding';
import RiskGauge from './components/RiskGauge';

const JargonText: React.FC<{ text: string }> = ({ text }) => {
  const jargonKeys = Object.keys(JARGON_EXPLANATIONS);
  const regex = new RegExp(`(\\b(?:${jargonKeys.join('|')})\\b)`, 'g');
  const parts = text.split(regex);

  return (
    <>
      {parts.map((part, i) => {
        const explanation = JARGON_EXPLANATIONS[part];
        if (explanation) {
          return (
            <span key={i} className="relative group cursor-help border-b-2 border-dotted border-blue-400/50 text-blue-700 font-bold px-0.5 hover:bg-blue-50 transition-colors rounded-sm">
              {part}
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 w-64 p-4 bg-slate-900/95 backdrop-blur-sm text-white text-[11px] rounded-2xl opacity-0 group-hover:opacity-100 transition-all pointer-events-none z-[100] shadow-2xl leading-relaxed scale-95 group-hover:scale-100 origin-bottom">
                <span className="block font-black mb-2 border-b border-slate-700 pb-1 text-blue-300 uppercase tracking-widest">{part} Definition</span>
                {explanation}
              </span>
            </span>
          );
        }
        return part;
      })}
    </>
  );
};

const DocumentContextView: React.FC<{ 
  text: string, 
  clauses: FlaggedClause[], 
  hoveredIndex: number | null, 
  onHover: (idx: number | null) => void,
  onScrollTo: (idx: number) => void
}> = ({ text, clauses, hoveredIndex, onHover, onScrollTo }) => {
  if (!text) return null;

  let content: React.ReactNode[] = [text];

  clauses.forEach((clause, idx) => {
    const newContent: React.ReactNode[] = [];
    content.forEach((item) => {
      if (typeof item !== 'string') {
        newContent.push(item);
        return;
      }

      const parts = item.split(clause.clauseText);
      parts.forEach((part, i) => {
        newContent.push(part);
        if (i < parts.length - 1) {
          const riskColors = {
            high: 'bg-red-100 text-red-900 border-red-200',
            medium: 'bg-amber-100 text-amber-900 border-amber-200',
            low: 'bg-emerald-100 text-emerald-900 border-emerald-200'
          };

          newContent.push(
            <mark
              key={`${idx}-${i}`}
              onMouseEnter={() => onHover(idx)}
              onMouseLeave={() => onHover(null)}
              onClick={() => onScrollTo(idx)}
              className={`px-1 rounded-md border cursor-pointer transition-all duration-300 ${
                riskColors[clause.riskLevel]
              } ${hoveredIndex === idx ? 'ring-4 ring-blue-500/30 scale-[1.02] shadow-lg z-10' : 'opacity-80 hover:opacity-100'}`}
            >
              {clause.clauseText}
              <span className="ml-1 text-[8px] font-black uppercase align-top bg-white/50 px-1 rounded-sm">Issue #{idx + 1}</span>
            </mark>
          );
        }
      });
    });
    content = newContent;
  });

  return (
    <div className="bg-white border border-slate-200 rounded-[2.5rem] p-10 shadow-inner overflow-y-auto max-h-[70vh] custom-scrollbar text-sm leading-relaxed text-slate-500 font-medium whitespace-pre-wrap">
      <div className="sticky top-0 bg-white/90 backdrop-blur-md -mt-10 -mx-10 p-6 border-b border-slate-100 mb-6 z-20 flex justify-between items-center">
        <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Full Document Text</h4>
        <div className="flex gap-2">
          <div className="w-2 h-2 rounded-full bg-red-400"></div>
          <div className="w-2 h-2 rounded-full bg-amber-400"></div>
          <div className="w-2 h-2 rounded-full bg-emerald-400"></div>
        </div>
      </div>
      {content}
    </div>
  );
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [rawText, setRawText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [thresholds, setThresholds] = useState<RiskThresholds>({ lowMax: 30, mediumMax: 70 });
  const [selectedIndices, setSelectedIndices] = useState<number[]>([]);
  const [isComparing, setIsComparing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [activeHighlight, setActiveHighlight] = useState<number | null>(null);
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [privateNotes, setPrivateNotes] = useState<Record<number, string>>({});
  const [exportConfig, setExportConfig] = useState<ExportOptions>({
    includeClauses: true,
    includeContext: false,
    includeScores: true,
    includeNotes: true,
    includeRecommendations: true
  });

  const t = TRANSLATIONS[lang];
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const hasSeen = localStorage.getItem('contractcheck_onboarding_seen');
    if (!hasSeen) setShowOnboarding(true);
    const localThresholds = localStorage.getItem('contractcheck_thresholds');
    if (localThresholds) setThresholds(JSON.parse(localThresholds));
  }, []);

  const getLevel = (score: number, thresh: RiskThresholds): RiskLevel => {
    if (score <= thresh.lowMax) return 'low';
    if (score <= thresh.mediumMax) return 'medium';
    return 'high';
  };

  const adjustedAnalysis = useMemo(() => {
    if (!analysis) return null;
    return {
      ...analysis,
      overallRisk: getLevel(analysis.overallRiskScore, thresholds),
      flaggedClauses: analysis.flaggedClauses.map((c, idx) => ({
        ...c,
        riskLevel: getLevel(c.riskScore, thresholds),
        privateNote: privateNotes[idx] || ''
      }))
    };
  }, [analysis, thresholds, privateNotes]);

  const processText = async (text: string) => {
    setLoading(true); setError(null); setAnalysis(null); setRawText(text); setProgress(30);
    setLoadingText('Searching for risks...');
    try {
      const result = await analyzeContract(text);
      setAnalysis(result);
      setPrivateNotes({});
    } catch (err: any) {
      setError(err.message || 'Analysis failed. Please try again.');
    } finally {
      setLoading(false); setProgress(0);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | undefined;
    if ('dataTransfer' in e) {
      e.preventDefault(); e.stopPropagation(); setIsDragging(false);
      file = e.dataTransfer.files[0];
    } else {
      file = e.target.files?.[0];
    }
    if (!file) return;
    if (file.type !== 'application/pdf') {
      setError('Please upload a PDF file.');
      return;
    }

    setLoading(true); setProgress(5); setLoadingText('Reading document...');
    try {
      const text = await parsePDF(file);
      setProgress(20); await processText(text);
    } catch (err: any) {
      setError('Could not read PDF.'); setLoading(false);
    }
  };

  const loadSample = (key: string) => {
    setAnalysis(PRE_ANALYZED_SAMPLES[key]);
    setRawText(`Example ${key} document content.\n\n` + PRE_ANALYZED_SAMPLES[key].flaggedClauses.map(c => c.clauseText).join('\n\n') + '\n\nEnd of example.');
    setPrivateNotes({});
    setSelectedIndices([]);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToClause = (idx: number) => {
    setActiveHighlight(idx);
    cardRefs.current[idx]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setTimeout(() => setActiveHighlight(null), 3000);
  };

  const toggleSelection = (idx: number) => {
    setSelectedIndices(prev => {
      if (prev.includes(idx)) return prev.filter(i => i !== idx);
      if (prev.length < 2) return [...prev, idx];
      return [prev[1], idx];
    });
  };

  const handleNoteChange = (idx: number, note: string) => {
    setPrivateNotes(prev => ({ ...prev, [idx]: note }));
  };

  const executeExport = () => {
    if (!adjustedAnalysis) return;

    let report = `CONTRACTCHECK REPORT\nDate: ${new Date().toLocaleString()}\n`;
    report += `Summary: ${adjustedAnalysis.overallRisk.toUpperCase()} RISK (Score: ${adjustedAnalysis.overallRiskScore}/100)\n\n`;

    if (exportConfig.includeContext) {
      report += `DOC TEXT:\n${rawText.substring(0, 500)}...\n\n`;
    }

    report += `ISSUES FOUND:\n${'='.repeat(20)}\n\n`;

    adjustedAnalysis.flaggedClauses.forEach((c, i) => {
      report += `${i + 1}. ${c.issue}\n`;
      if (exportConfig.includeClauses) report += `The Clause: "${c.clauseText}"\n`;
      report += `Why it's a risk: ${c.analysis}\n`;
      if (exportConfig.includeRecommendations) report += `What to do: ${c.recommendation}\n`;
      if (exportConfig.includeNotes && c.privateNote) report += `My Notes: ${c.privateNote}\n`;
      report += `\n`;
    });

    const blob = new Blob([report], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `contract_check_${Date.now()}.txt`;
    a.click();
    setShowExportModal(false);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col antialiased text-slate-900 selection:bg-blue-100 selection:text-blue-900">
      {showOnboarding && <Onboarding onClose={(ds) => { if (ds) localStorage.setItem('contractcheck_onboarding_seen', 'true'); setShowOnboarding(false); }} />}

      {/* Export Config Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[110] bg-slate-950/40 backdrop-blur-md flex items-center justify-center p-6 fade-in">
          <div className="bg-white rounded-[3rem] shadow-3xl max-w-md w-full p-10 border border-slate-100">
            <h3 className="text-2xl font-black text-slate-900 mb-2">Save Report</h3>
            <p className="text-slate-500 text-sm mb-8 font-medium">Choose what to include in your file.</p>

            <div className="space-y-4 mb-10">
              {Object.entries(exportConfig).map(([key, value]) => (
                <label key={key} className="flex items-center justify-between cursor-pointer group">
                  <span className="text-xs font-black text-slate-600 uppercase tracking-widest">{key.replace('include', '')}</span>
                  <input 
                    type="checkbox" 
                    checked={value} 
                    onChange={(e) => setExportConfig(prev => ({ ...prev, [key]: e.target.checked }))}
                    className="w-5 h-5 rounded-md border-2 border-slate-200 text-blue-600 focus:ring-blue-500 transition-all"
                  />
                </label>
              ))}
            </div>

            <div className="flex gap-4">
              <Button variant="ghost" className="flex-1 font-black text-xs uppercase" onClick={() => setShowExportModal(false)}>Cancel</Button>
              <Button className="flex-1 font-black text-xs uppercase shadow-xl shadow-blue-500/20" onClick={executeExport}>Save File</Button>
            </div>
          </div>
        </div>
      )}

      {/* Comparison Drawer */}
      {isComparing && adjustedAnalysis && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 sm:p-10 fade-in">
          <div className="bg-white w-full max-w-7xl rounded-[3.5rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b flex justify-between items-center bg-slate-50/80">
              <div>
                <h2 className="text-3xl font-black">Compare Issues</h2>
                <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Look at two clauses side-by-side</p>
              </div>
              <Button variant="ghost" size="sm" onClick={() => setIsComparing(false)}>Close</Button>
            </div>
            <div className="flex-1 overflow-y-auto p-12 grid grid-cols-1 md:grid-cols-2 gap-16">
              {selectedIndices.map((idx) => {
                const c = adjustedAnalysis.flaggedClauses[idx];
                return (
                  <div key={idx} className="space-y-8">
                    <div className="flex justify-between items-start">
                      <Badge level={c.riskLevel} label={c.riskLevel} />
                    </div>
                    <h3 className="text-3xl font-black leading-tight">{c.issue}</h3>
                    <div className="bg-slate-50 p-8 rounded-3xl italic text-slate-700 border border-slate-100 shadow-inner text-lg leading-relaxed">"{c.clauseText}"</div>
                    {c.privateNote && (
                      <div className="p-4 bg-blue-50/50 rounded-xl border border-blue-100 italic text-blue-700 text-xs font-medium">
                        My Note: {c.privateNote}
                      </div>
                    )}
                    <div className="space-y-6">
                      <div>
                        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Why it matters</h4>
                        <p className="text-md leading-relaxed text-slate-600"><JargonText text={c.analysis} /></p>
                      </div>
                      <div className="p-6 bg-emerald-50 rounded-[2rem] border border-emerald-100 shadow-sm">
                        <p className="text-xs font-black text-emerald-700 mb-2 uppercase tracking-tighter">Better Version</p>
                        <p className="text-md text-slate-700 font-medium">{c.recommendation}</p>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto px-6 sm:px-10 py-5 flex items-center justify-between">
          <div className="flex items-center gap-5 group cursor-pointer" onClick={() => window.location.reload()}>
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-500/20 group-hover:scale-110 transition-transform">
              <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
            </div>
            <div>
              <h1 className="text-2xl font-black tracking-tight text-slate-900 leading-none">ContractCheck</h1>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.3em] mt-1.5">South Africa</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
              {(['en', 'af', 'zu'] as Language[]).map(l => (
                <button key={l} onClick={() => setLang(l)} className={`px-4 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${lang === l ? 'bg-white text-blue-600 shadow-md scale-105' : 'text-slate-400 hover:text-slate-600'}`}>{l}</button>
              ))}
            </div>
            <Button variant="ghost" size="sm" onClick={() => setShowSettings(!showSettings)} className={showSettings ? "bg-blue-50 text-blue-600" : ""}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/></svg>
            </Button>
          </div>
        </div>
      </header>

      {showSettings && (
        <div className="bg-white border-b border-slate-200 p-10 fade-in no-print shadow-2xl relative z-30">
          <div className="max-w-5xl mx-auto space-y-8">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Risk Settings</h3>
            <div className="grid sm:grid-cols-2 gap-16">
              <div className="space-y-4">
                <div className="flex justify-between items-end"><label className="text-xs font-bold text-slate-700 uppercase">Low Risk Trigger</label><span className="text-emerald-600 font-black text-xs bg-emerald-50 px-2 py-1 rounded-md">{thresholds.lowMax}%</span></div>
                <input type="range" min="10" max="45" value={thresholds.lowMax} onChange={(e) => setThresholds({...thresholds, lowMax: parseInt(e.target.value)})} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-emerald-500" />
              </div>
              <div className="space-y-4">
                <div className="flex justify-between items-end"><label className="text-xs font-bold text-slate-700 uppercase">High Risk Trigger</label><span className="text-amber-600 font-black text-xs bg-amber-50 px-2 py-1 rounded-md">{thresholds.mediumMax}%</span></div>
                <input type="range" min={thresholds.lowMax + 5} max="85" value={thresholds.mediumMax} onChange={(e) => setThresholds({...thresholds, mediumMax: parseInt(e.target.value)})} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-amber-500" />
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl mx-auto w-full px-6 sm:px-10 py-12">
        {!adjustedAnalysis && !loading && (
          <div className="space-y-20 py-10">
            <div className="text-center space-y-6">
              <h2 className="text-7xl font-black text-slate-900 tracking-tighter leading-tight">Spot hidden traps in any contract.</h2>
              <p className="text-slate-500 max-w-2xl mx-auto text-xl leading-relaxed font-medium">Whether it's a house lease, a job offer, or a business deal, get an instant AI scan for South African legal safety.</p>
              <div className="flex flex-wrap justify-center gap-3 mt-8">
                <span className="px-4 py-2 bg-slate-100 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-200">Consumer Rights</span>
                <span className="px-4 py-2 bg-slate-100 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-200">Employment Law</span>
                <span className="px-4 py-2 bg-slate-100 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-200">Leases & Property</span>
                <span className="px-4 py-2 bg-slate-100 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-200">Privacy (POPIA)</span>
              </div>
            </div>

            <div 
              className={`relative border-[8px] border-dashed rounded-[5rem] p-32 text-center transition-all duration-700 bg-white group ${isDragging ? 'border-blue-500 bg-blue-50/50 scale-[1.02] shadow-3xl' : 'border-slate-100 hover:border-blue-200 hover:shadow-2xl'}`}
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={handleFileUpload}
            >
              <input type="file" accept=".pdf" ref={fileInputRef} onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer z-10" />
              <div className="space-y-10 relative z-0 pointer-events-none">
                <div className="w-28 h-28 bg-blue-50 rounded-[2.5rem] flex items-center justify-center mx-auto text-blue-600 group-hover:scale-110 group-hover:rotate-12 transition-all shadow-xl shadow-blue-500/10">
                  <svg className="w-14 h-14" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/></svg>
                </div>
                <div className="space-y-3">
                  <h3 className="text-4xl font-black text-slate-900 tracking-tight">Drop your contract here</h3>
                  <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">PDF Only • Safe & Private • SA Law Tuned</p>
                </div>
                <Button size="lg" className="shadow-3xl shadow-blue-600/30 font-black tracking-widest uppercase text-xs">Start AI Scan</Button>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
              {Object.keys(PRE_ANALYZED_SAMPLES).map(key => (
                <button key={key} onClick={() => loadSample(key)} className="p-12 bg-white border border-slate-100 rounded-[3.5rem] text-left hover:shadow-3xl hover:-translate-y-3 transition-all flex flex-col justify-between group overflow-hidden relative">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-50 rounded-bl-[5rem] translate-x-10 -translate-y-10 group-hover:translate-x-8 group-hover:-translate-y-8 transition-transform"></div>
                  <div className="relative z-10">
                    <Badge level={PRE_ANALYZED_SAMPLES[key].overallRisk} label="Example" />
                    <h4 className="text-3xl font-black text-slate-900 mt-6 leading-tight">Common {key} Risks</h4>
                    <p className="text-slate-500 text-md mt-4 leading-relaxed font-medium">See how we spot common problems in South African agreements.</p>
                  </div>
                  <div className="mt-10 flex items-center gap-3 text-blue-600 font-black text-xs uppercase tracking-[0.2em] group-hover:gap-6 transition-all">
                    Try Example <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 8l4 4m0 0l-4 4m4-4H3"/></svg>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {loading && (
          <div className="py-40 text-center space-y-12 fade-in">
            <div className="relative inline-flex mb-8">
              <div className="w-32 h-32 rounded-[3rem] border-8 border-blue-50 animate-pulse"></div>
              <div className="absolute inset-0 w-32 h-32 rounded-[3rem] border-8 border-blue-600 border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-4">
              <h3 className="text-5xl font-black text-slate-900 tracking-tighter">{loadingText}</h3>
              <p className="text-slate-400 text-xl font-bold uppercase tracking-widest">Checking the Law...</p>
            </div>
            <div className="max-w-xl mx-auto space-y-4">
              <div className="h-5 bg-slate-100 rounded-full overflow-hidden shadow-inner border border-slate-200">
                <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-600 transition-all duration-700 ease-out shadow-lg" style={{ width: `${progress}%` }}></div>
              </div>
            </div>
          </div>
        )}

        {adjustedAnalysis && (
          <div className="space-y-12 fade-in">
            {/* Action Bar */}
            <div className="bg-white/50 backdrop-blur-md p-5 rounded-[2rem] border border-slate-200 flex flex-wrap justify-between items-center gap-6 no-print shadow-sm">
              <Button variant="ghost" size="sm" onClick={() => setAnalysis(null)} className="font-black text-xs uppercase tracking-widest">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"/></svg> New Document
              </Button>
              <div className="flex gap-3 items-center">
                {selectedIndices.length === 2 && <Button size="sm" onClick={() => setIsComparing(true)} className="animate-pulse shadow-lg shadow-blue-500/20 font-black text-xs uppercase tracking-widest">Compare Two</Button>}
                <div className="flex gap-2 border-l pl-4 border-slate-200">
                  <Button size="sm" variant="secondary" onClick={() => setShowExportModal(true)} className="font-black text-xs uppercase tracking-widest">Save Result</Button>
                </div>
              </div>
            </div>

            <div className="grid lg:grid-cols-3 gap-12 items-start">
              {/* Left Column: Analysis Dashboard */}
              <div className="lg:col-span-2 space-y-12">
                <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 flex flex-col md:flex-row overflow-hidden">
                  <div className="p-16 flex flex-col items-center justify-center bg-slate-50 border-b md:border-b-0 md:border-r border-slate-100 min-w-[320px]">
                    <RiskGauge 
                      score={adjustedAnalysis.overallRiskScore} 
                      level={adjustedAnalysis.overallRisk} 
                      label={`${adjustedAnalysis.overallRisk} Risk`} 
                      clauses={adjustedAnalysis.flaggedClauses}
                    />
                  </div>
                  <div className="p-16 flex-1 space-y-8">
                    <div className="flex justify-between items-start">
                      <h3 className="text-4xl font-black text-slate-900 tracking-tight">AI Summary</h3>
                      <Badge level={adjustedAnalysis.overallRisk} label={`${adjustedAnalysis.overallRisk} Risk`} />
                    </div>
                    <p className="text-slate-600 leading-relaxed text-xl font-medium">
                      {adjustedAnalysis.flaggedClauses.length > 0 
                        ? `We found ${adjustedAnalysis.flaggedClauses.length} items that could be a problem. Look at the breakdown below.` 
                        : t.noIssues}
                    </p>
                    <div className="flex gap-3">
                      <div className="px-5 py-2.5 bg-blue-50 rounded-2xl border border-blue-100 text-[10px] font-black text-blue-700 uppercase tracking-widest shadow-sm">SA Law: Checked</div>
                      <div className="px-5 py-2.5 bg-emerald-50 rounded-2xl border border-emerald-100 text-[10px] font-black text-emerald-700 uppercase tracking-widest shadow-sm">Privacy: Safe</div>
                    </div>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="flex items-center justify-between px-6">
                    <h4 className="font-black text-slate-400 uppercase tracking-[0.3em] text-xs">Identified Issues</h4>
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Click cards to compare</p>
                  </div>

                  {adjustedAnalysis.flaggedClauses.map((clause, idx) => (
                    <div 
                      key={idx} 
                      ref={el => cardRefs.current[idx] = el}
                      onMouseEnter={() => setHoveredIndex(idx)}
                      onMouseLeave={() => setHoveredIndex(null)}
                      className={`bg-white rounded-[3rem] border-2 transition-all duration-500 overflow-hidden group/card ${
                        selectedIndices.includes(idx) ? 'border-blue-500 shadow-3xl scale-[1.01]' : 'border-slate-100 shadow-md hover:border-slate-200'
                      } ${hoveredIndex === idx ? 'ring-4 ring-blue-500/20 shadow-2xl' : ''} ${activeHighlight === idx ? 'ring-4 ring-blue-500 ring-offset-8 scale-105' : ''}`}
                    >
                      <div className={`h-3 w-full ${clause.riskLevel === 'high' ? 'bg-red-500' : clause.riskLevel === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                      <div className="p-12 space-y-10">
                        <div className="flex justify-between items-start">
                          <div className="space-y-2 cursor-pointer" onClick={() => toggleSelection(idx)}>
                            <div className="flex items-center gap-3">
                              <h5 className="text-3xl font-black text-slate-900 group-hover/card:text-blue-600 transition-colors tracking-tight">{clause.issue}</h5>
                            </div>
                            <div className="flex gap-2">
                              <Badge level={clause.riskLevel} label={`${clause.riskLevel} threat`} />
                            </div>
                          </div>
                          {clause.legislationLink && (
                            <a 
                              href={clause.legislationLink} 
                              target="_blank" 
                              rel="noopener noreferrer" 
                              className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-5 py-3 rounded-2xl hover:bg-blue-600 hover:text-white transition-all flex items-center gap-2 shadow-sm" 
                            >
                              Check Act <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
                            </a>
                          )}
                        </div>

                        <div className="bg-slate-50 p-10 rounded-[2.5rem] italic text-slate-700 leading-relaxed border border-slate-100 shadow-inner group-hover/card:bg-slate-100/50 transition-colors relative">
                          <p className="relative z-10 font-bold text-lg leading-relaxed">"{clause.clauseText}"</p>
                        </div>

                        <div className="grid md:grid-cols-2 gap-16 pt-6 border-t border-slate-50">
                          <div className="space-y-4">
                            <h6 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">Why it's a risk</h6>
                            <p className="text-slate-600 leading-relaxed font-medium"><JargonText text={clause.analysis} /></p>
                          </div>
                          <div className="space-y-4">
                            <h6 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2">What to do</h6>
                            <div className="p-6 bg-emerald-50/50 rounded-[2rem] border border-emerald-100/50 text-slate-800 leading-relaxed font-bold text-md shadow-sm">
                              {clause.recommendation}
                            </div>
                          </div>
                        </div>

                        {/* Notes Section */}
                        <div className="pt-8 border-t border-slate-100 space-y-4">
                          <h6 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">My Personal Notes</h6>
                          <textarea 
                            value={privateNotes[idx] || ''}
                            onChange={(e) => handleNoteChange(idx, e.target.value)}
                            placeholder="Add your own notes here..."
                            className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-5 text-sm font-medium text-slate-600 focus:ring-4 focus:ring-blue-100 focus:bg-white focus:border-blue-400 outline-none transition-all placeholder:text-slate-300 resize-none min-h-[100px]"
                          />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Right Column: Original Text */}
              <div className="lg:w-full shrink-0 no-print space-y-10 sticky top-32">
                <div className="space-y-6">
                  <h4 className="font-black text-slate-900 uppercase tracking-[0.2em] text-[10px] px-2">Document View</h4>
                  <DocumentContextView 
                    text={rawText} 
                    clauses={adjustedAnalysis.flaggedClauses} 
                    hoveredIndex={hoveredIndex}
                    onHover={setHoveredIndex}
                    onScrollTo={scrollToClause}
                  />
                </div>

                <div className="bg-slate-900 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                  <h5 className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-6">SA Laws Covered</h5>
                  <div className="space-y-5">
                    {Object.keys(JARGON_EXPLANATIONS).map((key) => (
                      <div key={key} className="flex items-center gap-4 group/item">
                        <div className="w-8 h-8 rounded-xl bg-white/10 flex items-center justify-center text-[10px] font-black text-white group-hover/item:bg-blue-600 transition-colors shadow-lg">{key[0]}</div>
                        <div className="text-xs font-bold text-slate-300 group-hover/item:text-white transition-colors uppercase tracking-widest">{key}</div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-100 py-24 mt-auto no-print">
        <div className="max-w-7xl mx-auto px-10 text-center space-y-12">
          <div className="flex flex-wrap justify-center gap-x-20 gap-y-8 opacity-40">
            <span className="text-[10px] font-black tracking-[0.5em] uppercase">Private Encryption</span>
            <span className="text-[10px] font-black tracking-[0.5em] uppercase">Consumer Rights</span>
            <span className="text-[10px] font-black tracking-[0.5em] uppercase">Privacy Ready</span>
          </div>
          <div className="max-w-2xl mx-auto space-y-6">
            <p className="text-[11px] text-slate-400 leading-relaxed font-bold uppercase tracking-tight px-6 opacity-60">
              ContractCheck is for education. It does not replace a real lawyer. Use it to understand your risks, but always get professional help before signing high-stakes deals.
            </p>
            <p className="text-[10px] font-black text-slate-300 tracking-[0.4em] uppercase">© {new Date().getFullYear()} CONTRACTCHECK SA</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

export type RiskLevel = 'high' | 'medium' | 'low';

export interface RiskThresholds {
  lowMax: number;
  mediumMax: number;
}

export interface FlaggedClause {
  clauseText: string;
  riskLevel: RiskLevel; 
  riskScore: number;    // 0 to 100
  issue: string;
  analysis: string;
  recommendation: string;
  legislationLink?: string; // Link to official SA gov legislation
  uncertainty?: string;
  privateNote?: string; // Local user note
}

export interface AnalysisResult {
  overallRisk: RiskLevel;
  overallRiskScore: number;
  flaggedClauses: FlaggedClause[];
  uncertainty?: string;
}

export interface SavedAnalysis {
  id: number;
  timestamp: string;
  encrypted: {
    salt: number[];
    iv: number[];
    data: number[];
  };
