import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

export async function analyzeContract(contractText: string): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const injectionPatterns = /ignore (previous|all) instructions|system prompt|<\|im_start\|>|<\|im_end\|>/i;
  if (injectionPatterns.test(contractText)) {
    throw new Error('Potential prompt injection detected. Analysis refused.');
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analyze this South African contract text. Identify high-risk or potentially unlawful clauses. 
    Focus on:
    - Consumer Protection Act (CPA)
    - Protection of Personal Information Act (POPIA)
    - Rental Housing Act (RHA)
    - Basic Conditions of Employment Act (BCEA)

    Contract Text:
    ---
    ${contractText.substring(0, 30000)}
    ---`,
    config: {
      systemInstruction: `You are a specialized South African legal analysis tool.

      TASKS:
      1. Find high-risk clauses and quote them VERBATIM.
      2. Rate overall risk (0-100).
      3. For each clause, provide a 'legislationLink' to an official South African government portal (e.g., gov.za) or a recognized legal summary of the relevant Act.

      OUTPUT:
      Return valid JSON using the provided schema.
      Use plain, accessible English in 'analysis' and 'recommendation' fields. Avoid overly technical jargon.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          overallRiskScore: { type: Type.NUMBER },
          overallRisk: { type: Type.STRING },
          flaggedClauses: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clauseText: { type: Type.STRING },
                riskScore: { type: Type.NUMBER },
                riskLevel: { type: Type.STRING },
                issue: { type: Type.STRING },
                analysis: { type: Type.STRING },
                recommendation: { type: Type.STRING },
                legislationLink: { type: Type.STRING },
              },
              required: ["clauseText", "riskScore", "issue", "analysis", "recommendation"]
            }
          }
        },
        required: ["overallRisk", "overallRiskScore", "flaggedClauses"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI model.");

  try {
    return JSON.parse(text) as AnalysisResult;
  } catch (e) {
    throw new Error("Invalid response format from AI.");
  }
}

