const JargonText: React.FC<{ text: string }> = ({ text }) => {
  const jargonKeys = Object.keys(JARGON_EXPLANATIONS);
  const regex = new RegExp(`(\\b(?:${jargonKeys.join('|')})\\b)`, 'g');
  const parts = text.split(regex);

  return (
    <>
      {parts.map((part, i) => {
        const explanation = JARGON_EXPLANATIONS[part];
        if (explanation) {
          return (
            <span key={i} className="relative group cursor-help border-b-2 border-dotted border-blue-400/50 text-blue-700 font-bold px-0.5 hover:bg-blue-50 transition-colors rounded-sm">
              {part}
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 w-64 p-4 bg-slate-900/95 backdrop-blur-sm text-white text-[11px] rounded-2xl opacity-0 group-hover:opacity-100 transition-all pointer-events-none z-[100] shadow-2xl leading-relaxed scale-95 group-hover:scale-100 origin-bottom">
                <span className="block font-black mb-2 border-b border-slate-700 pb-1 text-blue-300 uppercase tracking-widest">{part} Definition</span>
                {explanation}
              </span>
            </span>
          );
        }
        return part;
      })}
    </>
  );
};

const DocumentContextView: React.FC<{ 
  text: string, 
  clauses: FlaggedClause[], 
  hoveredIndex: number | null, 
  onHover: (idx: number | null) => void,
  onScrollTo: (idx: number) => void
}> = ({ text, clauses, hoveredIndex, onHover, onScrollTo }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  if (!text) return null;

  let content: React.ReactNode[] = [text];

  clauses.forEach((clause, idx) => {
    const newContent: React.ReactNode[] = [];
    content.forEach((item) => {
      if (typeof item !== 'string') {
        newContent.push(item);
        return;
      }

      const parts = item.split(clause.clauseText);
      parts.forEach((part, i) => {
        newContent.push(part);
        if (i < parts.length - 1) {
          const riskColors = {
            high: 'bg-red-200/60 text-red-900 border-red-300',
            medium: 'bg-amber-200/60 text-amber-900 border-amber-300',
            low: 'bg-emerald-200/60 text-emerald-900 border-emerald-300'
          };

          newContent.push(
            <mark
              key={`${idx}-${i}`}
              onMouseEnter={() => onHover(idx)}
              onMouseLeave={() => onHover(null)}
              onClick={() => onScrollTo(idx)}
              className={`px-0.5 rounded cursor-pointer transition-all duration-300 border-b-2 ${
                riskColors[clause.riskLevel]
              } ${hoveredIndex === idx ? 'ring-2 ring-blue-500 bg-blue-100 shadow-sm' : ''}`}
            >
              {clause.clauseText}
            </mark>
          );
        }
      });
    });
    content = newContent;
  });

  return (
    <div className="bg-white border border-slate-200 rounded-[2rem] shadow-sm flex flex-col h-[70vh] overflow-hidden">
      <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center shrink-0">
        <div className="flex items-center gap-2">
          <svg className="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
          <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Your Document</h4>
        </div>
        <div className="flex gap-1.5">
          <div className="w-2 h-2 rounded-full bg-slate-200"></div>
          <div className="w-2 h-2 rounded-full bg-slate-200"></div>
          <div className="w-2 h-2 rounded-full bg-slate-200"></div>
        </div>
      </div>
      <div 
        ref={containerRef}
        className="flex-1 p-8 overflow-y-auto custom-scrollbar text-sm leading-relaxed text-slate-600 font-medium whitespace-pre-wrap selection:bg-blue-100"
      >
        {content}
      </div>
    </div>
  );
};

