      const de = e as React.DragEvent;
      de.preventDefault();
      de.stopPropagation();
      setIsDragging(false);
      file = de.dataTransfer.files[0];
    } else {
      const ce = e as React.ChangeEvent<HTMLInputElement>;
      file = ce.target.files?.[0];
    }

    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError('Please use a PDF file.');
      return;
