import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

export async function analyzeContract(contractText: string): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const injectionPatterns = /ignore (previous|all) instructions|system prompt|<\|im_start\|>|<\|im_end\|>/i;
  if (injectionPatterns.test(contractText)) {
    throw new Error('Potential security risk detected. We cannot process this document.');
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analyze this South African agreement text for risks. 
    Focus on: Consumer Protection Act (CPA), POPIA, Job Law (BCEA), and Rental Law.

    Agreement Text:
    ---
    ${contractText.substring(0, 30000)}
    ---`,
    config: {
      systemInstruction: `You are a helpful South African legal assistant. 
      Analyze the text and find parts that might be unfair or illegal.

      RULES:
      1. Use PLAIN ENGLISH only. No complex jargon. Explain big words simply.
      2. Quote the specific parts (clauses) from the text EXACTLY.
      3. For each part found, provide a link to the official South African government website (gov.za) for the relevant law (CPA, POPIA, BCEA, or RHA).
      4. Score the overall risk out of 100.

      Return results as a clean JSON object based on the provided schema.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          overallRiskScore: { type: Type.NUMBER },
          overallRisk: { type: Type.STRING },
          flaggedClauses: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clauseText: { type: Type.STRING },
                riskScore: { type: Type.NUMBER },
                riskLevel: { type: Type.STRING },
                issue: { type: Type.STRING },
                analysis: { type: Type.STRING },
                recommendation: { type: Type.STRING },
                legislationLink: { type: Type.STRING },
              },
              required: ["clauseText", "riskScore", "issue", "analysis", "recommendation"]
            }
          }
        },
        required: ["overallRisk", "overallRiskScore", "flaggedClauses"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("The AI did not return a response.");

  try {
    return JSON.parse(text) as AnalysisResult;
  } catch (e) {
    throw new Error("We had trouble understanding the AI's response. Please try again.");
  }
}

