      return;
    }

    setLoading(true); setProgress(5); setLoadingText('Reading document...'); setError(null);
    try {
      const text = await parsePDF(file);
      setRawText(text);
      setLoadingText('Searching for traps...');
      setProgress(40);
      const result = await analyzeContract(text);
      setAnalysis(result);
      setPrivateNotes({});
    } catch (err: any) {
      setError(err.message || 'We could not process the file.');
    } finally {
      setLoading(false); setProgress(0);
    }
  };

  const toggleSelection = (idx: number) => {
    setSelectedIndices(prev => {
      if (prev.includes(idx)) return prev.filter(i => i !== idx);
      if (prev.length < 2) return [...prev, idx];
      return [prev[1], idx];
    });
  };

  const scrollToClause = (idx: number) => {
    setActiveHighlight(idx);
    cardRefs.current[idx]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setTimeout(() => setActiveHighlight(null), 3000);
  };

  const executeExport = () => {
    if (!analysis) return;
    let report = `CONTRACTCHECK SA - RISK REPORT\nDate: ${new Date().toLocaleString()}\n\n`;

    if (exportConfig.mode === 'full') {
      report += `--- FULL DOCUMENT TEXT ---\n${rawText}\n\n`;
    }

    report += `--- RISK ANALYSIS SUMMARY ---\n`;
    report += `Overall Score: ${analysis.overallRiskScore}/100 (${analysis.overallRisk.toUpperCase()})\n\n`;

    analysis.flaggedClauses.forEach((c, i) => {
      report += `${i + 1}. ISSUE: ${c.issue}\n`;
      report += `TEXT: "${c.clauseText}"\n`;
      report += `WHY: ${c.analysis}\n`;
      if (exportConfig.includeRecommendations) report += `DO THIS: ${c.recommendation}\n`;
      if (exportConfig.includeNotes && privateNotes[i]) report += `MY NOTE: ${privateNotes[i]}\n`;
      report += `\n`;
    });

    const blob = new Blob([report], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
