import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

export async function analyzeContract(contractText: string): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const injectionPatterns = /ignore (previous|all) instructions|system prompt|<\|im_start\|>|<\|im_end\|>/i;
  if (injectionPatterns.test(contractText)) {
    throw new Error('Potential security risk detected. We cannot process this document.');
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analyze this South African contract text for specific legal risks. 
    Focus on: Consumer Protection Act (CPA), POPIA, BCEA (Job law), and Rental Housing Act.

    Contract Text:
    ---
    ${contractText.substring(0, 30000)}
    ---`,
    config: {
      systemInstruction: `You are a world-class South African legal compliance expert. 
      Analyze the provided text and identify high-risk or unlawful clauses.

      CRITICAL RULES:
      1. Use PLAIN, SIMPLE ENGLISH. Avoid technical legal jargon where possible. If you must use it, explain it.
      2. Quote the clause text EXACTLY as it appears in the contract.
      3. For every identified issue, provide a direct URL to the relevant South African Act on a government or official portal (e.g., gov.za or legal databases).
      4. Score the overall risk from 0 to 100.

      OUTPUT: Return a JSON object strictly following the provided schema.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          overallRiskScore: { type: Type.NUMBER },
          overallRisk: { type: Type.STRING },
          flaggedClauses: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clauseText: { type: Type.STRING },
                riskScore: { type: Type.NUMBER },
                riskLevel: { type: Type.STRING },
                issue: { type: Type.STRING },
                analysis: { type: Type.STRING },
                recommendation: { type: Type.STRING },
                legislationLink: { type: Type.STRING },
              },
              required: ["clauseText", "riskScore", "issue", "analysis", "recommendation"]
            }
          }
        },
        required: ["overallRisk", "overallRiskScore", "flaggedClauses"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI model.");

  try {
    return JSON.parse(text) as AnalysisResult;
  } catch (e) {
    throw new Error("Failed to interpret the AI's analysis. Please try again.");
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Language, AnalysisResult, RiskLevel, RiskThresholds, FlaggedClause, ExportOptions } from './types';
import { TRANSLATIONS, PRE_ANALYZED_SAMPLES, JARGON_EXPLANATIONS } from './constants';
