          <div className="space-y-16 py-10">
            <div className="text-center space-y-6">
              <h2 className="text-6xl sm:text-7xl font-black text-slate-900 tracking-tighter leading-tight">Analyze any contract in seconds.</h2>
              <p className="text-slate-500 max-w-2xl mx-auto text-xl leading-relaxed font-medium">Spot unfair terms and legal traps in South African leases, job offers, or sales agreements using AI tailored for local law.</p>
            </div>

            {/* Optimized Drop Zone with dynamic states */}
            <div 
              className={`relative border-[8px] border-dashed rounded-[5rem] p-32 text-center transition-all duration-700 bg-white group ${isDragging ? 'border-blue-500 bg-blue-50/50 scale-[1.02] shadow-[0_0_50px_-12px_rgba(37,99,235,0.4)]' : 'border-slate-100 hover:border-blue-200 hover:shadow-xl'}`}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleFileUpload}
              aria-label="File upload drop area"
            >
              <input 
                type="file" 
                accept=".pdf" 
                className="absolute inset-0 opacity-0 cursor-pointer z-10" 
                onChange={handleFileUpload} 
                aria-hidden="true"
              />
              <div className="space-y-10 relative z-0 pointer-events-none">
                <div className={`w-28 h-28 rounded-[2.5rem] flex items-center justify-center mx-auto transition-all duration-500 shadow-xl ${isDragging ? 'bg-blue-600 text-white scale-125 rotate-12 animate-pulse' : 'bg-blue-50 text-blue-600 group-hover:scale-110'}`}>
                  <svg className="w-14 h-14" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
                  </svg>
                </div>
                <div className="space-y-3">
                  <h3 className="text-4xl font-black text-slate-900 tracking-tight transition-all duration-300">
                    {isDragging ? 'Drop it now!' : 'Drop PDF or Click to Upload'}
                  </h3>
                  <p className="text-slate-400 font-bold uppercase tracking-widest text-xs transition-opacity duration-300">
                    {isDragging ? 'Ready for scan...' : 'Privacy Guaranteed • SA Law Compliance • Instant Audit'}
                  </p>
                </div>
                {!isDragging && (
                  <Button size="lg" className="shadow-2xl shadow-blue-600/20 font-black uppercase text-xs tracking-widest pointer-events-none">
                    Select Document
                  </Button>
                )}
              </div>
            </div>

            {error && (
              <div className="p-8 bg-red-50 border border-red-100 rounded-[2.5rem] text-center flex flex-col items-center gap-4 fade-in">
                <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-red-600">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                </div>
                <p className="text-red-700 font-black text-lg">{error}</p>
                <Button variant="ghost" size="sm" onClick={() => setError(null)}>Clear and Retry</Button>
              </div>
            )}

            <div className="grid md:grid-cols-2 gap-8">
              {Object.keys(PRE_ANALYZED_SAMPLES).map(key => (
                <button key={key} onClick={() => loadSample(key)} className="p-12 bg-white border border-slate-100 rounded-[3.5rem] text-left hover:shadow-2xl hover:-translate-y-2 transition-all group relative overflow-hidden flex flex-col justify-between h-full">
                  <div className="relative z-10">
                    <Badge level={PRE_ANALYZED_SAMPLES[key].overallRisk} label={`${key} Demo`} />
                    <h4 className="text-3xl font-black text-slate-900 mt-6 leading-tight">Common {key} Risks</h4>
                    <p className="text-slate-500 text-md mt-4 leading-relaxed font-medium">See how ContractCheck identifies problematic clauses in a standard South African {key}.</p>
                  </div>
                  <div className="mt-8 flex items-center gap-2 text-blue-600 font-black uppercase text-[10px] tracking-widest group-hover:translate-x-2 transition-transform">
                    View Demo <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7l5 5m0 0l-5 5m5-5H6"/></svg>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {loading && (
          <div className="py-40 text-center space-y-12 fade-in">
            <div className="relative inline-flex mb-8">
              <div className="w-36 h-36 rounded-[4rem] border-[10px] border-blue-50 animate-pulse"></div>
              <div className="absolute inset-0 w-36 h-36 rounded-[4rem] border-[10px] border-blue-600 border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-4">
              <h3 className="text-5xl font-black text-slate-900 tracking-tighter">{loadingText}</h3>
              <p className="text-slate-400 font-black uppercase tracking-widest text-sm">Our AI is scanning every clause...</p>
            </div>
            <div className="max-w-xl mx-auto h-2.5 bg-slate-100 rounded-full overflow-hidden shadow-inner">
              <div className="h-full bg-blue-600 transition-all duration-700 ease-out shadow-lg" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        )}

        {analysis && (
          <div className="space-y-12 fade-in">
            <div className="bg-white p-5 rounded-[2rem] border border-slate-200 flex flex-wrap justify-between items-center gap-6 shadow-sm no-print sticky top-[92px] z-30">
              <Button variant="ghost" size="sm" onClick={() => { setAnalysis(null); setRawText(''); }} className="font-black text-xs uppercase tracking-widest">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"/></svg> New Analysis
              </Button>
              <div className="flex gap-3">
                {selectedIndices.length === 2 && (
                  <Button size="sm" onClick={() => setIsComparing(true)} className="animate-pulse shadow-lg shadow-blue-500/20 font-black text-xs uppercase tracking-widest">
                    Compare Selected ({selectedIndices.length})
                  </Button>
                )}
                <Button size="sm" variant="secondary" onClick={() => setShowExportModal(true)} className="font-black text-xs uppercase tracking-widest">Download Report</Button>
              </div>
            </div>

            <div className="grid lg:grid-cols-12 gap-12 items-start">
              <div className="lg:col-span-7 space-y-12">
                <div className="bg-white rounded-[3rem] shadow-xl border border-slate-100 p-12 flex flex-col md:flex-row gap-12 items-center">
                  <RiskGauge score={analysis.overallRiskScore} level={analysis.overallRisk} label={`${analysis.overallRisk} risk`} clauses={analysis.flaggedClauses} />
                  <div className="space-y-6 flex-1 text-center md:text-left">
                    <h3 className="text-4xl font-black text-slate-900 tracking-tight">AI Audit Result</h3>
                    <p className="text-slate-600 leading-relaxed font-medium">We identified {analysis.flaggedClauses.length} clauses that require your immediate attention based on South African consumer and labor laws.</p>
                    <div className="flex flex-wrap justify-center md:justify-start gap-2">
                      <span className="px-4 py-2 bg-blue-50 rounded-xl text-[10px] font-black text-blue-700 uppercase tracking-widest border border-blue-100">POPIA Verified</span>
                      <span className="px-4 py-2 bg-emerald-50 rounded-xl text-[10px] font-black text-emerald-700 uppercase tracking-widest border border-emerald-100">CPA Compliant</span>
                    </div>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="flex items-center justify-between px-2">
                    <h4 className="font-black text-slate-400 uppercase tracking-widest text-xs">Flagged Issues</h4>
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Select two to compare</span>
                  </div>
                  {analysis.flaggedClauses.map((clause, idx) => (
                    <div 
                      key={idx} ref={el => cardRefs.current[idx] = el}
                      onMouseEnter={() => setHoveredIndex(idx)} onMouseLeave={() => setHoveredIndex(null)}
                      className={`bg-white rounded-[2.5rem] border-2 transition-all duration-500 overflow-hidden relative group/card ${
                        selectedIndices.includes(idx) ? 'border-blue-500 shadow-2xl scale-[1.01]' : 'border-slate-100 shadow-md hover:border-slate-200 hover:shadow-lg'
                      } ${activeHighlight === idx ? 'ring-4 ring-blue-500 ring-offset-4 scale-[1.02]' : ''}`}
                    >
                      <button 
                        onClick={() => toggleSelection(idx)} 
                        className={`absolute top-8 right-8 w-10 h-10 rounded-full border-2 flex items-center justify-center transition-all ${selectedIndices.includes(idx) ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'border-slate-200 text-transparent hover:border-blue-300'}`}
                      >
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>
                      </button>

                      <div className={`h-2.5 w-full ${clause.riskLevel === 'high' ? 'bg-red-500' : clause.riskLevel === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>

                      <div className="p-12 space-y-10">
                        <div>
                          <Badge level={clause.riskLevel} label={`${clause.riskLevel} threat`} />
                          <h5 className="text-3xl font-black text-slate-900 mt-4 leading-tight">{clause.issue}</h5>
                        </div>

                        <div className="bg-slate-50 p-8 rounded-3xl italic text-slate-700 leading-relaxed border border-slate-100 shadow-inner group-hover/card:bg-slate-100/50 transition-colors font-medium">
                          "{clause.clauseText}"
                        </div>

                        <div className="grid md:grid-cols-2 gap-12">
                          <div className="space-y-4">
                            <h6 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Risk Analysis</h6>
                            <p className="text-md text-slate-600 leading-relaxed font-medium"><JargonText text={clause.analysis} /></p>
                          </div>
                          <div className="space-y-4">
                            <h6 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Expert Recommendation</h6>
                            <div className="p-6 bg-emerald-50 rounded-2xl border border-emerald-100 text-slate-800 text-sm font-bold shadow-sm leading-relaxed">
                              {clause.recommendation}
                            </div>
                          </div>
                        </div>

                        {clause.legislationLink && (
                          <div className="pt-6 border-t border-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                            <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Official Legislation Reference</span>
                            <a 
                              href={clause.legislationLink} 
                              target="_blank" 
                              rel="noopener noreferrer" 
                              className="text-[10px] font-black text-blue-600 uppercase flex items-center gap-1.5 hover:text-blue-800 transition-colors px-4 py-2 bg-blue-50 rounded-xl"
                            >
                              View Official Act <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
                            </a>
                          </div>
                        )}

                        <div className="pt-8 border-t border-slate-50 space-y-4">
                          <h6 className="text-[10px] font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
                            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z"/></svg>
                            Private Annotation
                          </h6>
                          <textarea 
                            value={privateNotes[idx] || ''} 
                            onChange={(e) => setPrivateNotes({...privateNotes, [idx]: e.target.value})} 
                            placeholder="Type your notes here... (Stored locally on your device)" 
                            className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-6 text-sm font-medium text-slate-600 focus:ring-4 focus:ring-blue-100 focus:bg-white focus:border-blue-400 outline-none transition-all placeholder:text-slate-300 resize-none shadow-inner" 
                            rows={3}
                          />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="lg:col-span-5 sticky top-48 space-y-8 no-print">
                <DocumentViewer 
                  text={rawText} 
                  clauses={analysis.flaggedClauses} 
                  hoveredIndex={hoveredIndex} 
                  onHover={setHoveredIndex} 
                  onScrollTo={scrollToClause} 
                />

                <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full -mr-16 -mt-16 group-hover:scale-150 transition-transform duration-700"></div>
                  <h5 className="text-[11px] font-black text-blue-400 uppercase tracking-[0.3em] mb-8 relative z-10">SA Law Knowledge Base</h5>
                  <div className="grid gap-4 relative z-10">
                    {Object.keys(JARGON_EXPLANATIONS).map((key) => (
                      <div key={key} className="flex items-center gap-4 p-4 rounded-2xl bg-white/5 hover:bg-white/10 transition-all cursor-help group/item border border-white/5">
                        <div className="w-8 h-8 rounded-xl bg-blue-600 flex items-center justify-center text-[11px] font-black text-white shadow-lg shadow-blue-600/20">{key[0]}</div>
                        <div className="text-[11px] font-bold text-slate-300 uppercase tracking-widest group-hover/item:text-white transition-colors">{key}</div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-100 py-24 mt-auto no-print">
        <div className="max-w-7xl mx-auto px-10 text-center space-y-10">
          <div className="flex justify-center gap-8">
             <div className="w-1.5 h-1.5 rounded-full bg-slate-200"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-slate-200"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-slate-200"></div>
          </div>
          <p className="text-[10px] text-slate-400 leading-relaxed font-bold uppercase tracking-[0.1em] max-w-xl mx-auto">
            Disclaimer: ContractCheck provides preliminary risk triage for educational awareness. It does not constitute legal advice and should not replace consultation with a qualified legal professional.
          </p>
          <div className="flex flex-col items-center gap-4">
            <p className="text-[11px] font-black text-slate-300 tracking-[0.5em] uppercase">ContractCheck SA</p>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Version 1.0.4 • Privacy-First Triage</p>
          </div>
        </div>
      </footer>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
        ::selection { background: #dbeafe; color: #1e40af; }
        @keyframes slideIn { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation: slideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default App;
